/**
 * Building one session out of more than one notebook.
 *
 * A session that jumped between languages card by card would fight the
 * learner, the text-to-speech voice and the direction of the script at
 * once, so a session across notebooks is each notebook's cards in a run,
 * one notebook after another, starting with the one being shown.
 *
 * Each notebook's cards are also built separately rather than from one
 * pooled list, which is what keeps a multiple-choice question honest: the
 * wrong answers are picked from the same notebook as the right one, so no
 * English card is ever offered a German distractor.
 */

/**
 * Shares one session's cap out between notebooks, in order.
 *
 * Every notebook is offered an equal share; what a short one does not use
 * goes to the notebooks after it, so a session is full whenever there are
 * enough cards to fill it. The order is the caller's — the notebook being
 * shown comes first, because that is the one the learner was looking at.
 */
export function shareOut<T>(lists: readonly (readonly T[])[], cap: number): T[] {
  // Tracked side by side with the lists, so no index can be missing.
  const shares = lists.map((list) => ({ list, size: list.length, take: 0 }));
  let left = cap;
  let open = shares.filter((share) => share.size > 0).length;

  // How many each notebook gets is settled first, round by round: everyone
  // is offered an equal share, and a notebook that runs out simply stops
  // being offered, so what it did not use falls to the others.
  while (left > 0 && open > 0) {
    const each = Math.max(1, Math.floor(left / open));
    open = 0;
    for (const share of shares) {
      if (left <= 0) break;
      const room = Math.min(each, share.size - share.take, left);
      share.take += room;
      left -= room;
      if (share.take < share.size) open += 1;
    }
  }

  // Only then are they laid out, each notebook's cards in one run, so the
  // language changes once per notebook rather than once per card.
  return shares.flatMap((share) => share.list.slice(0, share.take));
}
