/**
 * How long the answer stays after the first card was answered "Knew it" from
 * its front. Longer than a button's grade (`CORRECT_SHOWN_MS`): it is the
 * one look at the answer, and here there is no Undo to catch a false
 * "I know it" (strict review B3).
 */
const FIRST_FRONT_KNEW_MS = 1200;

/** A graded first card still face down after this long turns (longer than any flight home). */
const FIRST_FACE_DOWN_MS = 400;

/** The coach's demo waits for the answer to settle in (its entrance) and a breath more. */
const FIRST_COACH_DELAY_MS = 520;

/** The three quick cards: a flashcard, then a gap (or a reverse card), then spelling. */
export const FIRST_CARDS = 3;

/** The deck name the first answer is logged with (`/session?deck=first`). */
export const FIRST_DECK = 'first';

/** What the screen needs about the word, read once as it opens. */
interface FirstWord {
  word: Word;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  grading: GradingMode;
  /** Swipe to answer on this device (the switch and the coach). */
  swipe: StoredSwipe;
}

async function loadFirst(wordId: string): Promise<FirstWord | null> {
  const [word, notebooks, settings, swipe] = await Promise.all([
    getWord(wordId),
    listNotebooks(),
    loadSettings(),
    loadSwipe(),
  ]);
  if (word === undefined) return null;
  const notebook = notebooks.find((one) => one.id === word.notebookId);
  return {
    word,
    targetLang: notebook?.targetLang ?? 'en',
    meaningLang: notebook?.meaningLang ?? 'en',
    grading: settings?.typedGrading ?? defaultSettings().typedGrading,
    swipe,
  };
}

/** The first sense's parts, for the cards. */
function senseOf(word: Word): { meaning: string; gloss: string | undefined; example: string | undefined } {
  const first = word.meanings?.[0];
  const gloss = first?.gloss?.trim();
  return {
    meaning: first?.meaning.trim() ?? '',
    gloss: gloss === '' ? undefined : gloss,
    example: (word.meanings ?? [])
      .flatMap((sense) => sense.examples ?? [])
      .map((example) => example.sentence.trim())
      .find((sentence) => sentence !== ''),
  };
}

/** A sentence with the word (as it appears in it) cut out, or undefined when it is not there. */
function splitAround(
  word: Word,
  sentence: string,
): { before: string; answer: string; after: string } | undefined {
  const cloze = clozeOf({ id: word.id, headword: word.headword, meaning: '', examples: [sentence] });
  if (cloze === undefined) return undefined;
  const [before = '', after = ''] = cloze.sentence.split('_____');
  return { before, answer: cloze.answer, after };
}

type Step = { phase: 'practice'; index: number } | { phase: 'done' } | { phase: 'remind' };

/**
 * The first practice of the learner's own first word (onboarding v2 spec
 * §4.9): three quick cards of that one word, in the session's own frame,
 * then the celebration and, in the phone and desktop apps, the reminder ask. Only the
 * flashcard is graded (right is box 2, due tomorrow; wrong is box 1, back
 * later today); the gap and the spelling are practice and record nothing,
 * because under the real rules a miss there would move the box and make
 * the celebration's promise untrue.
 */
export function FirstPractice(): React.JSX.Element {
  const [params] = useSearchParams();
  const wordId = params.get('word') ?? '';
  const navigate = useNavigate();
  const [first, setFirst] = useState<FirstWord | null | undefined>(undefined);
  useEffect(() => {
    let live = true;
    void loadFirst(wordId).then((loaded) => {
      if (live) setFirst(loaded);
    });
    return () => {
      live = false;
    };
  }, [wordId]);

  const [step, setStep] = useState<Step>({ phase: 'practice', index: 0 });
  useNoSideScrollBack();
  const [graded, setGraded] = useState<GradeResult | undefined>(undefined);
  // First-run ends here: where the learner was heading before it, else Today.
  const toToday = useCallback((): void => {
    void navigate(takeAfterSetup() ?? '/', { replace: true });
  }, [navigate]);

  // The session's answers go as it ends, as a normal session's do.
  const finished = step.phase !== 'practice';
  useEffect(() => {
    if (finished) void practiceEnded();
  }, [finished]);

  if (first === null) return <Navigate to="/" replace />;
  if (first === undefined) return <main className={styles.screen} aria-busy="true" />;

  if (step.phase === 'done') {
    return (
      <FirstWin
        headword={first.word.headword}
        lang={first.targetLang}
        box={graded?.progress.box ?? 1}
        streak={graded?.streakAfter ?? 0}
        onContinue={() => {
          // The phone and desktop apps ask about the reminder now; a browser
          // tab keeps its own offer (WebReminderOffer) where it always was.
          if (remindsHere()) setStep({ phase: 'remind' });
          else toToday();
        }}
      />
    );
  }
  if (step.phase === 'remind') return <FirstReminderAsk onDone={toToday} />;

  return (
    <Cards
      key={step.index}
      first={first}
      index={step.index}
      onGraded={setGraded}
      onNext={() => {
        setStep(
          step.index + 1 < FIRST_CARDS ? { phase: 'practice', index: step.index + 1 } : { phase: 'done' },
        );
      }}
      onClose={() => {
        setStep({ phase: 'done' });
      }}
    />
  );
}

type Outcome = 'right' | 'wrong' | undefined;

function Cards({
  first,
  index,
  onGraded,
  onNext,
  onClose,
}: {
  first: FirstWord;
  index: number;
  onGraded: (result: GradeResult) => void;
  onNext: () => void;
  onClose: () => void;
}): React.JSX.Element {
  const { word, targetLang, meaningLang, grading } = first;
  const swipeOn = !first.swipe.off;
  const sense = senseOf(word);
  const parts = sense.example === undefined ? undefined : splitAround(word, sense.example);
  // Card 2 needs the word inside its own example; without one it is a reverse card.
  const kind = index === 0 ? 'flash' : index === 1 ? (parts === undefined ? 'reverse' : 'gap') : 'spell';

  const [flipped, setFlipped] = useState(false);
  const [outcome, setOutcome] = useState<Outcome>(undefined);
  const swipe = useRef<SwipeHandle>(null);
  const knewSide = useKnewSide();
  const showsKeys = useShowsKeys();
  const [typed, setTyped] = useState('');
  const shownAt = useRef(0);
  const sessionId = useRef<string | undefined>(undefined);
  const heading = useRef<HTMLHeadingElement>(null);
  const next = useRef<HTMLButtonElement>(null);
  const input = useRef<HTMLInputElement>(null);
  const frame = useRef<HTMLElement>(null);
  const keyboard = useSoftKeyboard(frame);
  // The latest onNext, so the timer below is not restarted by a new render.
  const onNextRef = useRef(onNext);
  useEffect(() => {
    onNextRef.current = onNext;
  });

  // Each card is its own mount (keyed by its index), so it starts face down
  // and clear; it is timed from now, with focus on its question.
  useEffect(() => {
    shownAt.current = performance.now();
    heading.current?.focus({ preventScroll: true });
  }, [index]);

  /** Moves on; the flashcard leaves towards its answer's side (or `dir`, a swipe's). */
  const moveOn = useCallback(
    (dir?: Direction): void => {
      if (kind === 'flash') {
        swipe.current?.leave(dir ?? (outcome === 'wrong' ? (-knewSide as Direction) : knewSide));
      }
      onNextRef.current();
    },
    [kind, outcome, knewSide],
  );

  // A right answer moves on by itself; a wrong one waits for Next (the waitAfterMistake rule).
  // A card held by a finger waits for it.
  const [dragging, setDragging] = useState(false);
  /** Answered "Knew it" from the front: its answer stays a little longer to be read. */
  const [fromFront, setFromFront] = useState(false);
  useEffect(() => {
    if (outcome === 'right' && !dragging) {
      const timer = window.setTimeout(
        () => {
          moveOn();
        },
        fromFront ? FIRST_FRONT_KNEW_MS : CORRECT_SHOWN_MS,
      );
      return () => {
        window.clearTimeout(timer);
      };
    }
    if (outcome === 'wrong') next.current?.focus();
    return undefined;
  }, [outcome, dragging, moveOn, fromFront]);

  const settle = (right: boolean): void => {
    setOutcome(right ? 'right' : 'wrong');
    if (right) platform.haptics.correct();
    else platform.haptics.wrong();
  };

  const grade = (right: boolean): void => {
    if (outcome !== undefined) return;
    settle(right);
    sessionId.current ??= crypto.randomUUID();
    void gradeCard(
      {
        wordId: word.id,
        correct: right,
        cardType: 'classic',
        source: 'session',
        deck: FIRST_DECK,
        latencyMs: performance.now() - shownAt.current,
        sessionId: sessionId.current,
      },
      localTimeZone(),
    ).then((result) => {
      onGraded(result);
      void syncPractice();
    });
  };

  /**
   * From the front, before it was turned. Unlike a session, the first
   * practice has no Undo, so a card answered "Knew it" is never thrown
   * unseen: it turns to its answer, which stays `FIRST_FRONT_KNEW_MS`, then
   * moves on (strict review B3). A miss turns and waits, as everywhere. A
   * swiped card turns once it is home (`onLanded`), a key's at once.
   */
  const turnOnLanding = useRef(false);
  const answerFromFront = (right: boolean, by: 'swipe' | 'key'): void => {
    if (outcome !== undefined) return;
    grade(right);
    if (right) setFromFront(true);
    if (by === 'swipe') turnOnLanding.current = true;
    else setFlipped(true);
  };
  const onLanded = (): void => {
    if (!turnOnLanding.current) return;
    turnOnLanding.current = false;
    setFlipped(true);
  };
  // Never a graded flashcard face down, as in a session (round 2 review R1).
  const faceDownGraded = kind === 'flash' && !flipped && outcome !== undefined && !dragging;
  useEffect(() => {
    if (!faceDownGraded) return undefined;
    const timer = window.setTimeout(() => {
      turnOnLanding.current = false;
      setFlipped(true);
    }, FIRST_FACE_DOWN_MS);
    return () => {
      window.clearTimeout(timer);
    };
  }, [faceDownGraded]);

  /** A swipe let go past the point (the session's rules, uiux spec §8). */
  const onSwipe = (dir: Direction): void => {
    if (outcome !== undefined) {
      moveOn(dir);
      return;
    }
    const knew = dir === knewSide;
    void noteSwiped(!flipped);
    if (!flipped) {
      answerFromFront(knew, 'swipe');
      return;
    }
    grade(knew);
    // A right answer from the back is thrown and the next card is there at once.
    if (knew) moveOn(dir);
  };

  // The swipe coach's first lesson plays here, on the first card anybody turns.
  const [coachRun, setCoachRun] = useState<CoachRun>({});
  const coachKey = `first-${String(index)}`;
  const coach =
    kind === 'flash' && swipeOn
      ? coachStep(first.swipe, coachRun, {
          key: coachKey,
          flip: true,
          flipped,
          graded: outcome !== undefined,
          showsKeys,
        })
      : null;
  if (coach === 'back' && coachRun.backOn !== coachKey) setCoachRun({ ...coachRun, backOn: coachKey });
  useEffect(() => {
    if (coachRun.backOn !== undefined) void noteCoach('back');
  }, [coachRun.backOn]);
  useEffect(() => {
    if (coach !== 'back' || reducedMotion()) return undefined;
    const timer = window.setTimeout(() => {
      swipe.current?.demo();
    }, FIRST_COACH_DELAY_MS);
    return () => {
      window.clearTimeout(timer);
    };
  }, [coach]);

  const answer = kind === 'gap' ? (parts?.answer ?? word.headword) : word.headword;
  const check = (): void => {
    if (outcome !== undefined || typed.trim() === '') return;
    settle(accepts(typed, answer, grading));
  };

  const progress = (index + 1) / FIRST_CARDS;
  const dir = directionOf(targetLang);

  return (
    <main ref={frame} className={styles.screen} {...keyboardAttributes(keyboard)}>
      <div className={styles.top}>
        <button
          type="button"
          className={cx(styles.close, 'pressSmall')}
          aria-label={t('onb.p.close')}
          onClick={onClose}
        >
          <Icon name="close" size={20} weight={2} />
        </button>
        <div
          className={styles.track}
          role="progressbar"
          aria-label={t('onb.p.card', { n: index + 1 })}
          aria-valuenow={index + 1}
          aria-valuemin={1}
          aria-valuemax={FIRST_CARDS}
        >
          <i className={styles.fill} style={{ transform: `scaleX(${String(progress)})` }} />
        </div>
        <span className={styles.count} aria-hidden="true">
          {index + 1}/{FIRST_CARDS}
        </span>
      </div>

      <div className={styles.body}>
        <span className={styles.kind}>
          {t(
            kind === 'flash'
              ? 'onb.p.flash'
              : kind === 'gap'
                ? 'onb.p.gap'
                : kind === 'reverse'
                  ? 'onb.p.reverse'
                  : 'onb.p.spell',
          )}
        </span>
        <h1 ref={heading} className={styles.prompt} tabIndex={-1}>
          {t(
            kind === 'flash'
              ? 'onb.p.flashQ'
              : kind === 'gap'
                ? 'onb.p.gapQ'
                : kind === 'reverse'
                  ? 'onb.p.reverseQ'
                  : 'onb.p.spellQ',
          )}
        </h1>

        <CardFrame
          swipeable={kind === 'flash'}
          swipe={swipe}
          host={frame}
          cardKey={coachKey}
          knewSide={knewSide}
          mode={!swipeOn ? 'off' : outcome !== undefined ? 'next' : 'grade'}
          face={flipped ? 'back' : 'front'}
          onCommit={onSwipe}
          onLanded={onLanded}
          onDrag={setDragging}
        >
          <div
            className={cx(
              styles.card,
              outcome === 'right' && styles.right,
              outcome === 'wrong' && styles.wrong,
            )}
          >
            {kind === 'flash' && !flipped && (
              <>
                <Bilingual lang={targetLang} className={styles.word} block>
                  {word.headword}
                </Bilingual>
                <SpeakButton text={word.headword} lang={targetLang} />
                <p className={styles.tip}>{t('onb.p.flashTip')}</p>
              </>
            )}
            {kind === 'flash' && flipped && (
              <>
                <Bilingual lang={targetLang} className={cx(styles.word, styles.wordSmall)} block>
                  {word.headword}
                </Bilingual>
                {sense.gloss !== undefined ? (
                  <>
                    <Bilingual lang={targetLang} className={styles.mean} block>
                      {sense.gloss}
                    </Bilingual>
                    {sense.meaning !== '' && sense.meaning !== sense.gloss && (
                      <Bilingual lang={meaningLang} className={styles.ex} block>
                        {sense.meaning}
                      </Bilingual>
                    )}
                  </>
                ) : (
                  <Bilingual lang={meaningLang} className={styles.mean} block>
                    {sense.meaning}
                  </Bilingual>
                )}
                {sense.example !== undefined && (
                  <Bilingual lang={targetLang} className={styles.ex} block>
                    {parts === undefined ? (
                      sense.example
                    ) : (
                      <>
                        {parts.before}
                        <b>{parts.answer}</b>
                        {parts.after}
                      </>
                    )}
                  </Bilingual>
                )}
                {outcome === 'wrong' && <p className={styles.tip}>{t('onb.p.noTip')}</p>}
              </>
            )}

            {kind === 'gap' && parts !== undefined && (
              <p className={styles.cloze} dir={dir} lang={targetLang}>
                {parts.before}
                <span className={styles.gap}>
                  {Array.from(parts.answer)
                    .map((char, at) => (at === 0 ? char : '_'))
                    .join('')}
                </span>
                {parts.after}
              </p>
            )}
            {kind === 'reverse' && (
              <Bilingual lang={meaningLang} className={styles.mean} block>
                {sense.meaning}
              </Bilingual>
            )}
            {kind === 'spell' && (
              <>
                <button
                  type="button"
                  className={cx(styles.bigSpeak, 'press')}
                  aria-label={t('onb.p.hear')}
                  onClick={() => {
                    platform.tts.speak(word.headword, ttsLocaleOf(targetLang));
                  }}
                >
                  <Icon name="speaker" size={30} weight={2} />
                </button>
                <Bilingual
                  lang={sense.gloss === undefined ? meaningLang : targetLang}
                  className={styles.ex}
                  block
                >
                  {sense.gloss ?? sense.meaning}
                </Bilingual>
              </>
            )}
            {kind !== 'flash' && (
              <>
                <input
                  ref={input}
                  className={styles.answer}
                  value={typed}
                  dir={dir}
                  lang={targetLang}
                  aria-label={t('onb.p.answer')}
                  placeholder={t(kind === 'spell' ? 'onb.p.spellPh' : 'onb.p.gapPh')}
                  autoComplete="off"
                  autoCapitalize="off"
                  autoCorrect="off"
                  spellCheck={false}
                  enterKeyHint="done"
                  readOnly={outcome !== undefined}
                  onChange={(event) => {
                    setTyped(event.target.value);
                  }}
                  onKeyDown={(event) => {
                    if (event.key === 'Enter') {
                      event.preventDefault();
                      check();
                    }
                  }}
                />
                {outcome === 'wrong' && (
                  <p className={styles.tip} role="status">
                    {t('onb.p.itIs')
                      .split('{word}')
                      .map((piece, at) =>
                        at === 0 ? (
                          <span key={at}>{piece}</span>
                        ) : (
                          <span key={at}>
                            <Bilingual lang={targetLang}>
                              <b>{answer}</b>
                            </Bilingual>
                            {piece}
                          </span>
                        ),
                      )}
                  </p>
                )}
              </>
            )}
            {outcome === 'right' && (
              <span className={styles.badge} role="status" aria-label={t('onb.p.right')}>
                <Icon name="check" size={16} weight={2.8} />
              </span>
            )}
          </div>
        </CardFrame>
      </div>

      <div className={styles.foot}>
        {coach === 'back' && (
          <p className={styles.coachLine} aria-hidden="true">
            {t('swipe.coachBack')}
          </p>
        )}
        {outcome === 'wrong' ? (
          <button
            type="button"
            ref={next}
            className={cx(styles.primary, styles.nextButton, 'press')}
            onClick={() => {
              moveOn();
            }}
          >
            {t('onb.p.next')}
          </button>
        ) : kind === 'flash' && !flipped ? (
          <button
            type="button"
            className={cx(styles.primary, styles.showAnswer, 'press')}
            aria-keyshortcuts="Space"
            onClick={() => {
              setFlipped(true);
            }}
          >
            {t('onb.p.show')}
          </button>
        ) : kind === 'flash' ? (
          <div className={styles.duo}>
            <button
              type="button"
              className={cx(styles.no, 'press')}
              disabled={outcome !== undefined}
              aria-keyshortcuts={knewSide === 1 ? 'ArrowLeft' : 'ArrowRight'}
              onClick={() => {
                swipe.current?.stopDemo();
                grade(false);
              }}
            >
              {t('onb.p.no')}
            </button>
            <button
              type="button"
              className={cx(styles.yes, 'press')}
              disabled={outcome !== undefined}
              aria-keyshortcuts={knewSide === 1 ? 'ArrowRight' : 'ArrowLeft'}
              onClick={() => {
                swipe.current?.stopDemo();
                grade(true);
              }}
            >
              {t('onb.p.yes')}
            </button>
          </div>
        ) : (
          <button
            type="button"
            className={cx(styles.primary, 'press')}
            disabled={typed.trim() === '' || outcome !== undefined}
            onClick={check}
          >
            {t('onb.p.check')}
          </button>
        )}
      </div>
      <KeyHandler
        active={kind === 'flash' && outcome === undefined}
        flipped={flipped}
        onFlip={() => {
          setFlipped(true);
        }}
        onGrade={(dir) => {
          swipe.current?.stopDemo();
          const knew = dir === knewSide;
          if (flipped) grade(knew);
          else answerFromFront(knew, 'key');
        }}
      />
    </main>
  );
}

/**
 * The flashcard's keys, as in a session (never while typing): Space turns
 * it, ← and → answer it, from the front too. A held key does nothing more.
 */
function KeyHandler({
  active,
  flipped,
  onFlip,
  onGrade,
}: {
  active: boolean;
  flipped: boolean;
  onFlip: () => void;
  onGrade: (dir: Direction) => void;
}): null {
  useEffect(() => {
    if (!active) return undefined;
    const onKey = (event: KeyboardEvent): void => {
      const target = event.target as HTMLElement | null;
      if (target?.tagName === 'INPUT') return;
      const arrow = event.key === 'ArrowLeft' || event.key === 'ArrowRight';
      if (arrow) {
        event.preventDefault();
        if (!event.repeat) onGrade(event.key === 'ArrowRight' ? 1 : -1);
        return;
      }
      if (event.key !== ' ' || flipped || target?.tagName === 'BUTTON') return;
      event.preventDefault();
      if (!event.repeat) onFlip();
    };
    window.addEventListener('keydown', onKey);
    return () => {
      window.removeEventListener('keydown', onKey);
    };
  }, [active, flipped, onFlip, onGrade]);
  return null;
}

/** The first card swipes; the practice cards after it are typed, and do not. */
function CardFrame({
  swipeable,
  swipe,
  children,
  ...props
}: Omit<React.ComponentProps<typeof SwipeCard>, 'ref' | 'flip' | 'radius'> & {
  swipeable: boolean;
  swipe: React.RefObject<SwipeHandle | null>;
}): React.JSX.Element {
  if (!swipeable) return <>{children}</>;
  return (
    <SwipeCard ref={swipe} flip radius="var(--r-lg)" {...props}>
      {children}
    </SwipeCard>
  );
}

/** The headword's speaker, absent when the device has no voice for the language. */
function SpeakButton({ text, lang }: { text: string; lang: LanguageCode }): React.JSX.Element | null {
  const canSpeak = useCanSpeak(lang);
  if (!canSpeak) return null;
  return (
    <button
      type="button"
      className={cx(styles.speak, 'pressSmall')}
      aria-label={t('action.speak')}
      onClick={() => {
        platform.tts.speak(text, ttsLocaleOf(lang));
      }}
    >
      <Icon name="speaker" size={16} weight={1.9} />
    </button>
  );
}
