/**
 * The swipe coach (uiux `specs/2026-10-25-practice-swipe.md` §9): which
 * lesson, if any, the card on screen gives about swiping.
 *
 * Not a tip. Tips are capped per day, never reach somebody who practised
 * before, and "Show tips" turns them off; swiping is news for every learner,
 * old or new, and the first lesson must not be lost to a cap. It is still
 * one line (and on a touch screen one short move of the card), never a
 * modal. Only "Swipe to answer" switches it off.
 *
 * Pure: the screen passes what this device remembers and what the card is
 * doing, and gets back the step to show.
 */
import type { StoredSwipe } from '@/db/schema.js';

/** Sessions in which the demo on a turned card plays, until the learner swipes. */
export const COACH_BACK_SESSIONS = 3;

/** Sessions in which the line on a card's front shows, until the learner swipes from one. */
export const COACH_FRONT_SESSIONS = 2;

/**
 * - `back`: on a turned flashcard, the card nudges right then left and one
 *   line says what each way means.
 * - `front`: on a later front, one line says it can be answered unturned.
 */
export type CoachStep = 'back' | 'front';

/** What this run of the session has already shown, and on which card. */
export interface CoachRun {
  /** The card the demo played on in this run. */
  backOn?: string | undefined;
  /** The card the front line showed on in this run. */
  frontOn?: string | undefined;
}

/** What the card on screen is doing. */
export interface CoachCard {
  key: string;
  /** A flashcard, recall or listening card: the kinds a swipe grades. */
  flip: boolean;
  flipped: boolean;
  graded: boolean;
  /** A keyboard is to hand (`useShowsKeys`): the keys on the buttons are the lesson there. */
  showsKeys: boolean;
}

/** The step this card shows now, or null. */
export function coachStep(state: StoredSwipe | null, run: CoachRun, card: CoachCard): CoachStep | null {
  if (state === null || state.off || !card.flip || card.graded || card.showsKeys) return null;

  if (card.flipped) {
    // A demo that played on this card keeps its line until the card is graded.
    if (run.backOn !== undefined) return run.backOn === card.key ? 'back' : null;
    return !state.swiped && state.backDemos < COACH_BACK_SESSIONS ? 'back' : null;
  }

  if (run.frontOn !== undefined) return run.frontOn === card.key ? 'front' : null;
  // One lesson at a time: a run that already gave the demo on another card
  // says nothing more, and the front line waits for somebody who has seen it.
  if (run.backOn !== undefined) return null;
  return !state.swipedFront && state.frontLines < COACH_FRONT_SESSIONS && state.backDemos >= 1
    ? 'front'
    : null;
}

/** The demo, in full (spec §9.3): a nudge towards Knew it, back, a nudge towards Didn't know, back. */
export const COACH_DEMO_MS = 1800;

/**
 * How far each nudge goes, as a share of the distance that answers: far
 * enough to show the real move (the pill and the button lit as they will be
 * at that point of a real drag), short of answering.
 */
export const COACH_NUDGE_SHARE = 0.75;

/** Each nudge's tilt. */
export const COACH_TILT_DEG = 3;

/** How lit the pill, the ring and the button get at each nudge: what a real drag that far shows. */
export const COACH_PEAK = COACH_NUDGE_SHARE;

/** The demo's moments in ms: out, hold, back, for each side in turn. */
export const COACH_TIMES = { out: 340, hold: 600, back: 900, out2: 1240, hold2: 1500 } as const;

/**
 * Where the demo is at `ms`: the side it leans to (+1 is Knew it's side
 * once multiplied by `knewSide`), and how lit it is. The card's own move
 * runs on Web Animations with the same moments; this keeps the pill and
 * the button in step with it.
 */
export function demoAt(ms: number): { side: 1 | -1; lit: number } {
  const { out, hold, back, out2, hold2 } = COACH_TIMES;
  const rise = (from: number, to: number): number =>
    COACH_PEAK * Math.min(1, Math.max(0, (ms - from) / (to - from)));
  if (ms < hold) return { side: 1, lit: rise(0, out) };
  if (ms < back) return { side: 1, lit: COACH_PEAK - rise(hold, back) };
  if (ms < hold2) return { side: -1, lit: rise(back, out2) };
  return { side: -1, lit: Math.max(0, COACH_PEAK - rise(hold2, COACH_DEMO_MS)) };
}
