import { useEffect, useState } from 'react';
import type { KnewSide } from './physics.js';

/**
 * The side "Knew it" is on: right on a left-to-right page, left on a
 * right-to-left one, because a swipe follows the buttons, never the card's
 * text (spec §7.9). The app is laid out left to right in every language
 * today, so this is +1; it is read, not assumed, so it stays true.
 */
export function useKnewSide(): KnewSide {
  const [side] = useState<KnewSide>(() => (document.documentElement.dir === 'rtl' ? -1 : 1));
  return side;
}

/**
 * While a practice screen is open, a sideways drift of two fingers on a
 * trackpad does not take the browser Back (Chrome and Firefox on a Mac; Safari
 * ignores it, and nothing is lost there: answers are saved as they are given).
 */
export function useNoSideScrollBack(): void {
  useEffect(() => {
    const root = document.documentElement;
    const before = root.style.overscrollBehaviorX;
    root.style.overscrollBehaviorX = 'none';
    return () => {
      root.style.overscrollBehaviorX = before;
    };
  }, []);
}
