/**
 * Swipe to answer, as numbers (uiux `specs/2026-10-25-practice-swipe.md` §2).
 *
 * Pure: the gesture hands in where the finger is and how fast it moves, and
 * gets back which way the drag is going, how far along it is and whether
 * letting go answers the card. Every number a learner can feel is a named
 * constant here with a test, so a screen never tunes a swipe on its own.
 *
 * Right is "Knew it" and left is "Didn't know" because that is where the two
 * buttons sit. The side follows the buttons, never the card's text: a
 * Persian meaning runs right to left, the buttons under it do not.
 */

/** +1 when "Knew it" is on the right (a left-to-right page), -1 when it is on the left. */
export type KnewSide = 1 | -1;

/** Which way a drag points: +1 right, -1 left. */
export type Direction = 1 | -1;

/** Movement before the gesture decides what the finger is doing; under it a press is a tap. */
export const SWIPE_SLOP_PX = 10;

/**
 * Sideways only if the move is this much more across than down at the slop.
 * Anything steeper is a scroll, so a long answer stays readable with a
 * slightly crooked thumb.
 */
export const SWIPE_LOCK_RATIO = 1.2;

/** A finger held still this long before moving is a press or a text selection, never a swipe. */
export const SWIPE_HOLD_MS = 450;

/** No drag starts this close to the left or right edge: the system's back gestures live there. */
export const SWIPE_EDGE_GUARD_PX = 24;

/** The commit distance is this share of the card's width… */
export const SWIPE_COMMIT_FRACTION = 0.28;

/** …never under this, so a narrow card does not answer on a twitch… */
export const SWIPE_COMMIT_MIN_PX = 72;

/** …and never over this, so a tablet's wide card does not need an arm's reach. */
export const SWIPE_COMMIT_MAX_PX = 120;

/** Once armed, a drag disarms only below this share of the distance: one tick, no flicker. */
export const SWIPE_DISARM_FRACTION = 0.85;

/** A flick this fast (px per ms) answers from a short drag… */
export const SWIPE_FLICK_SPEED = 0.55;

/** …if it travelled at least this far the same way, so a tap that slid is never a flick. */
export const SWIPE_FLICK_MIN_PX = 32;

/** The release speed is read over this last stretch of the gesture. */
export const SWIPE_VELOCITY_WINDOW_MS = 80;

/** A finger that stood still this long before lifting was not flicking. */
export const SWIPE_STILL_MS = 50;

/** Let go while moving back towards the middle this fast, and it cancels, even past the point. */
export const SWIPE_CANCEL_BACK_SPEED = 0.3;

/**
 * The card tilts this many degrees per card-width travelled (about 6° at
 * 100 px on a phone), so a wide card tilts no more than a narrow one at the
 * same share of the way, and its top does not swing into the question above…
 */
export const SWIPE_ROTATE_PER_WIDTH = 20;

/** …up to this, about the angle of a card held at its foot and pushed. */
export const SWIPE_MAX_ROTATE_DEG = 10;

/** Past the card's own width the drag meets resistance at this rate. */
export const SWIPE_OVERDRAG = 0.4;

/** The most a card that cannot be swiped moves: enough to say so without a word. */
export const SWIPE_RUBBER_PX = 16;

/** How quickly the rubber band reaches its limit (the tanh's scale, in px). */
export const SWIPE_RUBBER_SCALE_PX = 60;

/** A thrown card leaves in at least this… */
export const THROW_MIN_MS = 160;

/** …and at most this, whatever the flick. */
export const THROW_MAX_MS = 260;

/** A slower flick is read as this speed for the throw, so a card let go gently still leaves briskly. */
export const THROW_FLOOR_SPEED = 0.8;

/** The thrown card's final tilt. */
export const THROW_ROTATE_DEG = 14;

/** A card graded by a button, a key or a timer leaves with this tilt. */
export const LEAVE_ROTATE_DEG = 8;

/** The drag distance that answers on release, for a card this wide. */
export function commitPx(width: number): number {
  return Math.min(SWIPE_COMMIT_MAX_PX, Math.max(SWIPE_COMMIT_MIN_PX, width * SWIPE_COMMIT_FRACTION));
}

/**
 * What a move from the press has settled on: still a tap (undefined), a
 * swipe (`x`), a scroll (`y`), or a press held too long to be a swipe
 * (`hold`).
 */
export function lockAxis(dx: number, dy: number, heldMs: number): 'x' | 'y' | 'hold' | undefined {
  if (Math.hypot(dx, dy) < SWIPE_SLOP_PX) return undefined;
  if (heldMs > SWIPE_HOLD_MS) return 'hold';
  return Math.abs(dx) >= Math.abs(dy) * SWIPE_LOCK_RATIO ? 'x' : 'y';
}

/** The side a drag points to. */
export function directionOf(dx: number): Direction {
  return dx < 0 ? -1 : 1;
}

/**
 * How far towards answering a drag is: 0 at rest, 1 at the commit
 * distance, capped there. The pill, the ring and the button all follow it.
 */
export function progressOf(dx: number, width: number): number {
  return Math.min(1, Math.abs(dx) / commitPx(width));
}

/**
 * Whether the drag is armed now, given whether it was a moment ago: it arms
 * at the commit distance and disarms only well short of it.
 */
export function armedNow(dx: number, width: number, wasArmed: boolean): boolean {
  const distance = commitPx(width);
  return Math.abs(dx) >= (wasArmed ? distance * SWIPE_DISARM_FRACTION : distance);
}

/**
 * What letting go does (§2). A quick move back towards the middle cancels,
 * even past the point, which is how somebody changes their mind; past the
 * distance answers; so does a quick flick the way it travelled.
 */
export function decideRelease(dx: number, vx: number, width: number): 'commit' | 'cancel' {
  if (dx !== 0 && Math.sign(vx) === -Math.sign(dx) && Math.abs(vx) >= SWIPE_CANCEL_BACK_SPEED) {
    return 'cancel';
  }
  if (Math.abs(dx) >= commitPx(width)) return 'commit';
  if (
    Math.abs(vx) >= SWIPE_FLICK_SPEED &&
    Math.sign(vx) === Math.sign(dx) &&
    Math.abs(dx) >= SWIPE_FLICK_MIN_PX
  ) {
    return 'commit';
  }
  return 'cancel';
}

/** One reading of the pointer, for the release speed. */
export interface Sample {
  x: number;
  at: number;
}

/**
 * The speed of the moves (never the lift, which repeats the last place and
 * would halve a flick) over the `SWIPE_VELOCITY_WINDOW_MS` before the last
 * one, in px per ms (positive is rightwards); 0 when the finger stood still
 * for `SWIPE_STILL_MS` before it lifted.
 */
export function velocityOf(samples: readonly Sample[], now: number): number {
  const last = samples[samples.length - 1];
  if (last === undefined || now - last.at > SWIPE_STILL_MS) return 0;
  const recent = samples.filter((sample) => last.at - sample.at <= SWIPE_VELOCITY_WINDOW_MS);
  const first = recent[0];
  if (first === undefined || recent.length < 2) return 0;
  const elapsed = last.at - first.at;
  return elapsed <= 0 ? 0 : (last.x - first.x) / elapsed;
}

/** Whether a press starts in the band a phone keeps for its own edge gestures. */
export function inEdgeGuard(x: number, viewportWidth: number): boolean {
  return x < SWIPE_EDGE_GUARD_PX || x > viewportWidth - SWIPE_EDGE_GUARD_PX;
}

/** Where the card is drawn for a finger this far across: 1:1 to its width, then with resistance. */
export function followOf(raw: number, width: number): number {
  const reach = Math.abs(raw);
  if (reach <= width) return raw;
  return Math.sign(raw) * (width + (reach - width) * SWIPE_OVERDRAG);
}

/** The card's tilt at this offset, in degrees, for a card this wide. */
export function tiltOf(dx: number, width: number): number {
  if (width <= 0) return 0;
  return Math.sign(dx) * Math.min((Math.abs(dx) / width) * SWIPE_ROTATE_PER_WIDTH, SWIPE_MAX_ROTATE_DEG);
}

/** Where a card that cannot be swiped is drawn: it gives a little and no more. */
export function rubberOf(raw: number): number {
  return SWIPE_RUBBER_PX * Math.tanh(raw / SWIPE_RUBBER_SCALE_PX);
}

/** How long a thrown card takes to cover what is left of its way, at the speed it was let go. */
export function throwMs(remainingPx: number, vx: number): number {
  const ms = (1.6 * Math.max(0, remainingPx)) / Math.max(Math.abs(vx), THROW_FLOOR_SPEED);
  return Math.min(THROW_MAX_MS, Math.max(THROW_MIN_MS, ms));
}
