/**
 * The session state machine.
 *
 * It owns the queue, the current card, grading, the three-second undo, the
 * re-queue of a wrong answer and the summary. Everything it changes is
 * written through the data layer, so a session survives a reload and works
 * with no network at all.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  SESSION_CEILING,
  accepts,
  dayIndex,
  defaultSettings,
  type DailyLimits,
  type Deck,
  type EffectiveSchedule,
  type Word,
  type Kind,
  type PracticeScope,
  type Settings,
} from '@lexpad/core';
import {
  getActiveNotebook,
  listNotebooks,
  listWords,
  loadConfusions,
  loadSchedule,
  loadSettings,
} from '@/db/repo.js';
import { db } from '@/db/schema.js';
import { shareOut } from './scope.js';
import { gradeCard, setProgressFlags, undoGrade, type GradeResult } from '@/db/mutations.js';
import { platform } from '@/lib/platform/index.js';
import { localTimeZone } from '@/lib/format.js';
import { practiceEnded, practiceStarted, syncPractice, syncSoon } from '@/sync/store.js';
import { buildCards, type SessionCard } from './build.js';
import { smartRisk } from '@/features/schedule/capped.js';
import { AFTER_ANSWER_DEFAULT, waitsForNext, type AfterAnswer } from './pace.js';

/** No notebook: the starting value of `notDue`, one shared empty set. */
const NONE: ReadonlySet<string> = new Set();

/** How long the undo pill stays available after a grade. */
export const UNDO_WINDOW_MS = 3000;

/** What the summary screen shows. */
export interface SessionSummary {
  reviewed: number;
  correct: number;
  /** Words that reached the top box during this session. */
  mastered: Word[];
  /** Words answered wrongly at least once. */
  missed: Word[];
  /**
   * Words whose miss in this session brought them to the notebook's leech
   * threshold, with how many different days they have been missed on.
   */
  slipping: { word: Word; lapses: number }[];
  streak: number;
  /**
   * Which SRS v2 rules acted on this session's answers, for the summary's
   * link to "How words come back": an answer saved as practice (its box
   * kept), and a miss that went back two boxes rather than to the start.
   */
  rules: { kept: boolean; backTwo: boolean };
  /**
   * Where each word answered in this session went, in the order they were
   * first answered: the box it started the session in, the box and next
   * check its last answer left it with, and whether every answer was kept
   * as practice. "When they come back" on the summary reads it (the new
   * learner's journey, M4); it is the session's own answers, no read.
   */
  moves: WordMove[];
  /** The local day the session ran on, for the next check of each word. */
  today: number;
  /** The streak and the longest streak before the session's first answer (celebrations). */
  streakBefore: number;
  longestBefore: number;
  /**
   * Right answers to words that were due and last answered on an earlier
   * day, with how many days ago (celebrations: "You remembered … after …").
   * The first right answer to each word only; a re-asked card is not one.
   */
  recalls: { word: Word; days: number }[];
  /** Answers to words that were due, not new and not kept as practice. */
  dueAnswered: number;
}

/** One word's journey through a session, for the summary. */
export interface WordMove {
  word: Word;
  from: number;
  to: number;
  dueDay: number;
  /** Every answer to it was saved as practice: its box and day did not move. */
  kept: boolean;
}

/** The state a session screen renders. */
export interface SessionState {
  status: 'loading' | 'empty' | 'running' | 'finished';
  card: SessionCard | undefined;
  /** Cards answered so far, for the progress bar. */
  done: number;
  /** Position of the current card in the queue; alternates the entrance animation. */
  index: number;
  /** Cards in the queue, including re-queued ones. */
  total: number;
  /** Set once the current card has been answered, until the next one shows. */
  outcome: 'correct' | 'wrong' | undefined;
  /** The answer to reveal after a wrong typed or chosen answer. */
  revealed: string | undefined;
  /** True while the undo pill should be offered. */
  canUndo: boolean;
  /** What Undo would take back: the last answer's word and grade, for its name. */
  lastAnswer: { headword: string; notebookId: string; correct: boolean } | undefined;
  /** The word just mastered, for the celebration overlay. */
  celebrate: Word | undefined;
  /**
   * The box the word landed in, known only once it has been graded.
   *
   * The ladder is the whole model this app runs on and it used to move
   * entirely out of sight: you answered, the card left, and nothing said the
   * word had gone up or back to the start. Showing it is what makes the
   * next review make sense.
   */
  boxAfter: number | undefined;
  /**
   * Set once the current card has been answered as practice only: a right
   * answer to a word that was not due, in a notebook that keeps extra
   * practice out of the schedule. Its box did not move, and the screen says
   * so instead of showing a rung it did not climb.
   */
  practised: boolean;
  /**
   * The schedule of each notebook in this session, read when it started
   * (SRS v2). The session screen reads extra practice from it.
   */
  schedules: Record<string, EffectiveSchedule>;
  /**
   * The notebooks with a word in this session that is not due today, read
   * when it started. Only such a word can keep its box as extra practice,
   * so the session's line about it is said only for these (SRS v2).
   */
  notDue: ReadonlySet<string>;
  summary: SessionSummary;
  /** How many cards this deck still has, known once the session is over. */
  remaining: number;
}

interface Answered {
  card: SessionCard;
  correct: boolean;
  /** What the grade did, including the exact state it replaced. */
  graded: GradeResult;
  /** The key of the second try this miss put at the end, which Undo takes back out. */
  requeuedKey?: string;
}

/** What a session screen gets back from the hook. */
export interface SessionApi {
  state: SessionState;
  answer: (correct: boolean, extra?: { pickedWordId?: string; typed?: string }) => Promise<void>;
  answerTyped: (typed: string) => Promise<void>;
  answerChoice: (option: { wordId: string; label: string }) => Promise<void>;
  next: () => void;
  /**
   * Takes the last answer back. Resolves `'back'` when the card had already
   * moved on and is on screen again (a flashcard comes back face up),
   * `'here'` when it never left, nothing when there was nothing to take back.
   */
  undo: () => Promise<'here' | 'back' | undefined>;
  toggleStar: () => Promise<void>;
  saveNote: (memo: string) => Promise<void>;
}

/**
 * Runs one session over a deck. The deck and the day are fixed when the
 * session starts, so the queue does not shift under the learner.
 */
/** What a level, topic or kind deck practises. */
export interface DeckScope {
  level?: string;
  topic?: string;
  kind?: Kind;
}

export function useSession(
  deck: Deck,
  groupIds?: readonly string[],
  scope: DeckScope = {},
  /**
   * Which notebooks to draw from. 'all' runs through every notebook in
   * turn; anything else is the one being shown, which is how every screen
   * has always worked and stays the default.
   */
  across: PracticeScope = 'notebook',
  /**
   * A token that changes when the same deck is asked for again, which is
   * what the summary's "Keep going" does. It joins the shuffle seed, so
   * running a deck twice is not the same run twice.
   */
  again = '',
  /**
   * Settings → Practice → "After an answer" (pace.ts). An answered card that
   * waits for Next keeps its Undo for as long as it is on screen, rather
   * than for `UNDO_WINDOW_MS`: nothing is moving it on, so nothing should
   * take the way back away.
   */
  afterAnswer: AfterAnswer = AFTER_ANSWER_DEFAULT,
): SessionApi {
  const [cards, setCards] = useState<SessionCard[]>([]);
  const [index, setIndex] = useState(0);
  const [status, setStatus] = useState<SessionState['status']>('loading');
  const [outcome, setOutcome] = useState<SessionState['outcome']>(undefined);
  const [revealed, setRevealed] = useState<string | undefined>(undefined);
  const [celebrate, setCelebrate] = useState<Word | undefined>(undefined);
  const [canUndo, setCanUndo] = useState(false);
  /** The answer to the card on screen is recorded and can be taken back. */
  const [recorded, setRecorded] = useState(false);
  /**
   * The last answer's card has moved on, and Undo would bring it back. Undo
   * lasts `UNDO_WINDOW_MS` from the answer, also after the card has gone
   * (uiux 2026-10-25 swipe spec §5): a swipe to the right moves on at once,
   * and a mistaken swipe is the classic swipe error.
   */
  const [movedOn, setMovedOn] = useState(false);
  const [lastAnswered, setLastAnswered] = useState<SessionState['lastAnswer']>(undefined);
  const [boxAfter, setBoxAfter] = useState<number | undefined>(undefined);
  const [practised, setPractised] = useState(false);
  const [schedules, setSchedules] = useState<Record<string, EffectiveSchedule>>({});
  const [notDue, setNotDue] = useState<ReadonlySet<string>>(NONE);
  const [answers, setAnswers] = useState<Answered[]>([]);
  const [mastered, setMastered] = useState<Word[]>([]);
  const [streak, setStreak] = useState(0);
  const [typedGrading, setTypedGrading] = useState(defaultSettings().typedGrading);
  const [remaining, setRemaining] = useState(0);

  const undoTimer = useRef<number | undefined>(undefined);
  const lastAnswer = useRef<Answered | undefined>(undefined);
  const timeZone = useMemo(() => localTimeZone(), []);
  /**
   * One id for this run of the session, sent with every answer so the
   * server can tell sessions apart. "Keep going" (a new `again`) is a new
   * run. Made on the first answer, not during render.
   */
  const run = useRef<{ again: string; id: string } | undefined>(undefined);
  /** When the current card was put in front of the learner, for latency. */
  const shownAt = useRef<number>(0);

  /**
   * The queue this deck gives right now, from local data.
   *
   * Shared by the two things that need it: opening a session, and counting
   * what is still waiting once one has finished. They must agree -- the
   * number on "Keep going" is a promise about the session that button
   * opens, so it is worked out by building that very session rather than
   * by counting something near enough.
   */
  const buildQueue = useCallback(async (): Promise<
    | {
        cards: SessionCard[];
        typedGrading: Settings['typedGrading'];
        schedules: Record<string, EffectiveSchedule>;
        notDue: ReadonlySet<string>;
      }
    | undefined
  > => {
    const notebook = await getActiveNotebook();
    if (!notebook) return undefined;
    // The notebook being shown leads; the rest follow in their own
    // order. A session across notebooks is each one's cards in a run,
    // because a session that changed language card by card would fight
    // the learner, the voice and the script at once.
    const all = across === 'all' ? await listNotebooks() : [];
    const drawnFrom = [notebook, ...all.filter((one) => one.id !== notebook.id)];

    const today = dayIndex(new Date(), timeZone);
    // Each notebook's schedule is read once, here, and every grade of the
    // session uses it (SRS v2): its daily review limit shapes the daily
    // deck, and its rules move the boxes.
    const [perNotebook, confusions, settings, perSchedule, dayStat] = await Promise.all([
      Promise.all(drawnFrom.map((one) => listWords(one.id))),
      loadConfusions(),
      loadSettings(),
      Promise.all(drawnFrom.map((one) => loadSchedule(one.id))),
      db.dayStats.get(today),
    ]);
    const active = settings ?? defaultSettings();
    const limitsOf = (schedule: EffectiveSchedule | undefined, risk = smartRisk(schedule)): DailyLimits => ({
      ...(schedule !== undefined && schedule.reviewCap > 0 ? { reviewCap: schedule.reviewCap } : {}),
      ...(schedule?.perDayNew === true ? { newToday: dayStat?.newWords ?? 0 } : {}),
      // A Smart notebook's capped day is ordered by the chance of remembering each word.
      ...(risk === undefined ? {} : { smart: risk }),
    });
    // Built one notebook at a time rather than from one pooled list,
    // which is what keeps a multiple-choice question honest: the wrong
    // answers come from the same notebook as the right one.
    const cards = shareOut(
      drawnFrom.map((one, index) =>
        buildCards({
          words: perNotebook[index] ?? [],
          settings: active,
          deck,
          today,
          confusions,
          seed: `${one.id}:${today}:${deck}:${scope.level ?? ''}:${scope.topic ?? ''}:${scope.kind ?? ''}:${again}`,
          ...(groupIds ? { groupIds } : {}),
          scope,
          limits: limitsOf(perSchedule[index]),
        }),
      ),
      active.sessionCap,
    );
    const schedules: Record<string, EffectiveSchedule> = {};
    drawnFrom.forEach((one, index) => {
      const schedule = perSchedule[index];
      if (schedule !== undefined) schedules[one.id] = schedule;
    });
    const notDue = new Set(
      cards
        .filter((card) => card.word.progress !== undefined && card.word.progress.dueDay > today)
        .map((card) => card.word.notebookId),
    );
    return { cards, typedGrading: active.typedGrading, schedules, notDue };
  }, [deck, groupIds, scope, timeZone, across, again]);

  // A session pulls once as it starts (unless a pull is fresh) and pushes
  // and pulls once as it ends, closed part way or not; answers in between
  // go in batches (`syncPractice`).
  useEffect(() => {
    void practiceStarted();
    return () => {
      void practiceEnded();
    };
  }, []);

  // Build the queue once. An AbortController rather than a boolean flag, so
  // the compiler can see that the check after the awaits is meaningful.
  useEffect(() => {
    const aborter = new AbortController();
    void (async () => {
      const built = await buildQueue();
      if (aborter.signal.aborted) return;
      if (!built) {
        setStatus('empty');
        return;
      }
      setTypedGrading(built.typedGrading);
      setSchedules(built.schedules);
      setNotDue(built.notDue);
      setCards(built.cards);
      setStatus(built.cards.length === 0 ? 'empty' : 'running');
    })();
    return () => {
      aborter.abort();
      if (undoTimer.current !== undefined) window.clearTimeout(undoTimer.current);
    };
  }, [buildQueue]);

  /**
   * What this deck still has, counted once the session is over.
   *
   * The session is capped, so finishing one rarely means finishing the
   * deck: whatever the cap cut is still waiting, and so is anything that
   * was missed. Until this was counted the summary's "Keep going" was
   * given a default of nothing and never appeared at all.
   */
  useEffect(() => {
    if (status !== 'finished') return;
    // The summary is the end of the session: its answers go now.
    void practiceEnded();
    const aborter = new AbortController();
    void (async () => {
      const left = await buildQueue();
      if (aborter.signal.aborted) return;
      setRemaining(left?.cards.length ?? 0);
    })();
    return () => {
      aborter.abort();
    };
  }, [status, buildQueue]);

  const card = cards[index];

  // The clock for an answer starts when its card is shown, and again when an
  // undone card comes back.
  useEffect(() => {
    if (outcome === undefined) shownAt.current = performance.now();
  }, [card?.key, outcome]);

  /** Grades the current card and moves on. */
  const answer = useCallback(
    async (correct: boolean, extra: { pickedWordId?: string; typed?: string } = {}): Promise<void> => {
      if (!card || outcome !== undefined) return;

      const latencyMs = performance.now() - shownAt.current;
      if (run.current?.again !== again) run.current = { again, id: crypto.randomUUID() };
      const sessionId = run.current.id;
      setOutcome(correct ? 'correct' : 'wrong');
      if (!correct) {
        setRevealed(card.type === 'cloze' ? (card.clozeAnswer ?? card.word.headword) : card.word.headword);
      }
      if (correct) platform.haptics.correct();
      else platform.haptics.wrong();

      const result = await gradeCard(
        {
          wordId: card.word.id,
          correct,
          cardType: card.type,
          source: 'session',
          deck,
          requeued: card.requeued === true,
          latencyMs,
          sessionId,
          ...(extra.pickedWordId === undefined ? {} : { pickedWordId: extra.pickedWordId }),
          ...(extra.typed === undefined ? {} : { typed: extra.typed }),
          ...(schedules[card.word.notebookId] === undefined
            ? {}
            : { schedule: schedules[card.word.notebookId] }),
        },
        timeZone,
      );
      setStreak(result.streakAfter);
      // Practice only: the box did not move, so the chip stays where it is
      // and the screen says "Practice" rather than drawing a rung.
      setPractised(!result.scheduleChanged);
      setBoxAfter(result.scheduleChanged ? result.progress.box : undefined);

      // A wrong answer comes back once, at the end, unless the session is
      // full. It comes back from the box the miss put it in, so the chip of
      // the second try starts there and a right answer reads as a rise.
      const requeue = !correct && card.requeued !== true && cards.length < SESSION_CEILING;
      const requeuedKey = `${card.key}:again`;
      const answered: Answered = { card, correct, graded: result, ...(requeue ? { requeuedKey } : {}) };
      lastAnswer.current = answered;
      setLastAnswered({ headword: card.word.headword, notebookId: card.word.notebookId, correct });
      setAnswers((previous) => [...previous, answered]);

      if (result.mastered) {
        platform.haptics.success();
        setMastered((previous) => [...previous, card.word]);
        setCelebrate(card.word);
      }

      if (requeue) {
        setCards((previous) => [
          ...previous,
          {
            ...card,
            key: requeuedKey,
            requeued: true,
            isNew: false,
            box: result.progress.box,
            word: { ...card.word, progress: result.progress },
          },
        ]);
      }

      setCanUndo(true);
      setRecorded(true);
      setMovedOn(false);
      if (undoTimer.current !== undefined) window.clearTimeout(undoTimer.current);
      undoTimer.current = window.setTimeout(() => {
        setCanUndo(false);
      }, UNDO_WINDOW_MS);

      void syncPractice();
    },
    [card, cards.length, outcome, timeZone, deck, again, schedules],
  );

  /** Grades a typed answer, using the user's strictness setting. */
  const answerTyped = useCallback(
    async (typed: string): Promise<void> => {
      if (!card) return;
      await answer(accepts(typed, card.word.headword, typedGrading), { typed });
    },
    [answer, card, typedGrading],
  );

  /** Grades a chosen option. */
  const answerChoice = useCallback(
    async (option: { wordId: string; label: string }): Promise<void> => {
      if (!card) return;
      const expected = card.type === 'cloze' ? card.clozeAnswer : card.word.headword;
      const correct = option.wordId === card.word.id || option.label === expected;
      await answer(correct, correct ? {} : { pickedWordId: option.wordId });
    },
    [answer, card],
  );

  /** Shows the next card, or the summary when the queue is empty. */
  const next = useCallback((): void => {
    setOutcome(undefined);
    setBoxAfter(undefined);
    setPractised(false);
    setRevealed(undefined);
    setCelebrate(undefined);
    setRecorded(false);
    // An answer keeps its Undo on the next card for what is left of its
    // window; the summary has none.
    const last = index + 1 >= cards.length;
    if (last) setCanUndo(false);
    setMovedOn(!last && lastAnswer.current !== undefined);
    setIndex((previous) => {
      const following = previous + 1;
      if (following >= cards.length) {
        setStatus('finished');
        return previous;
      }
      return following;
    });
  }, [cards.length, index]);

  /** Reverts the last grade, within the undo window. */
  const held = recorded && outcome !== undefined && waitsForNext(afterAnswer, outcome);
  const undoable = canUndo || held;
  const undo = useCallback(async (): Promise<'here' | 'back' | undefined> => {
    const previous = lastAnswer.current;
    if (!previous || !undoable) return undefined;
    setCanUndo(false);
    setRecorded(false);
    if (undoTimer.current !== undefined) window.clearTimeout(undoTimer.current);
    // The exact state this grade replaced, read when it was made: for the
    // second try of a missed card that is the state after the first try.
    await undoGrade(previous.card.word.id, previous.graded, timeZone);
    setAnswers((entries) => entries.slice(0, -1));
    // The second try a miss queued goes with the miss: answered again, the
    // card queues its own (it used to stay, so an undone miss answered right
    // still came back, and one missed again came back twice).
    const { requeuedKey } = previous;
    if (requeuedKey !== undefined) {
      setCards((entries) => entries.filter((entry) => entry.key !== requeuedKey));
    }
    setMastered((entries) => entries.filter((word) => word.id !== previous.card.word.id));
    setOutcome(undefined);
    setBoxAfter(undefined);
    setPractised(false);
    setRevealed(undefined);
    setCelebrate(undefined);
    lastAnswer.current = undefined;
    setLastAnswered(undefined);
    // Gone on already: the card comes back to the screen.
    const back = movedOn;
    if (back) {
      setMovedOn(false);
      setIndex((at) => Math.max(0, at - 1));
    }
    void syncPractice();
    return back ? 'back' : 'here';
  }, [undoable, timeZone, movedOn]);

  /** Stars or unstars the current card's word. */
  const toggleStar = useCallback(async (): Promise<void> => {
    if (!card) return;
    const starred = card.word.progress?.starred !== true;
    const updated = await setProgressFlags(card.word.id, { starred }, timeZone);
    setCards((previous) =>
      previous.map((entry) =>
        entry.word.id === card.word.id ? { ...entry, word: { ...entry.word, progress: updated } } : entry,
      ),
    );
    void syncSoon();
  }, [card, timeZone]);

  /** Saves a note on the current card's word. */
  const saveNote = useCallback(
    async (memo: string): Promise<void> => {
      if (!card) return;
      const updated = await setProgressFlags(card.word.id, { memo }, timeZone);
      setCards((previous) =>
        previous.map((entry) =>
          entry.word.id === card.word.id ? { ...entry, word: { ...entry.word, progress: updated } } : entry,
        ),
      );
      void syncSoon();
    },
    [card, timeZone],
  );

  const summary: SessionSummary = useMemo(() => {
    const seen = new Map<string, Word>();
    for (const entry of answers) {
      if (!entry.correct) seen.set(entry.card.word.id, entry.card.word);
    }
    // A word is asked about once, for the latest of its leech answers.
    const slipping = new Map<string, { word: Word; lapses: number }>();
    for (const entry of answers) {
      if (entry.graded.leech) {
        slipping.set(entry.card.word.id, {
          word: entry.card.word,
          lapses: entry.graded.progress.lapses ?? 0,
        });
      }
    }
    const rules = { kept: false, backTwo: false };
    for (const entry of answers) {
      const { graded } = entry;
      if (!graded.scheduleChanged) rules.kept = true;
      const schedule = schedules[entry.card.word.notebookId];
      // Back two boxes acted only where the word did not land at the start anyway.
      if (
        !entry.correct &&
        graded.scheduleChanged &&
        schedule?.scheduler === 'boxes' &&
        schedule.afterMiss === 'back2' &&
        graded.progress.box > 1
      ) {
        rules.backTwo = true;
      }
    }
    const moves = new Map<string, WordMove>();
    for (const { card, graded } of answers) {
      const earlier = moves.get(card.word.id);
      moves.set(card.word.id, {
        word: card.word,
        from: earlier?.from ?? graded.before.box,
        to: graded.progress.box,
        dueDay: graded.progress.dueDay,
        kept: (earlier?.kept ?? true) && !graded.scheduleChanged,
      });
    }
    const recalls = new Map<string, { word: Word; days: number }>();
    let dueAnswered = 0;
    const day = dayIndex(new Date(), timeZone);
    for (const { card, graded, correct } of answers) {
      const before = graded.before;
      const wasDue = !graded.isNew && before.reps > 0 && before.dueDay <= day;
      if (!wasDue) continue;
      dueAnswered += 1;
      const last = before.lastDay;
      if (
        correct &&
        graded.scheduleChanged &&
        last !== undefined &&
        last < day &&
        !recalls.has(card.word.id)
      ) {
        recalls.set(card.word.id, { word: card.word, days: day - last });
      }
    }
    const [first] = answers;
    return {
      reviewed: answers.length,
      correct: answers.filter((entry) => entry.correct).length,
      mastered,
      missed: [...seen.values()],
      slipping: [...slipping.values()],
      streak,
      rules,
      moves: [...moves.values()],
      today: day,
      streakBefore: first?.graded.streakBefore ?? streak,
      longestBefore: first?.graded.longestBefore ?? streak,
      recalls: [...recalls.values()],
      dueAnswered,
    };
  }, [answers, mastered, streak, schedules, timeZone]);

  const state: SessionState = {
    status,
    card,
    done: answers.length,
    index,
    total: cards.length,
    outcome,
    revealed,
    canUndo: undoable,
    lastAnswer: lastAnswered,
    celebrate,
    boxAfter,
    practised,
    schedules,
    notDue,
    summary,
    remaining,
  };

  return { state, answer, answerTyped, answerChoice, next, undo, toggleStar, saveNote };
}
