/**
 * A card's stand-in on top of the page (uiux spec §6).
 *
 * A dragged, thrown or returning card is drawn by a copy of its element in
 * `document.body`, fixed over the real card, which stays where it is with
 * its opacity at 0 (so it keeps its focus and still takes the next press).
 * Two reasons. The session's stage is a scroll box, and a card moved inside
 * it was cut off at its edges, which on a tablet or a computer are well
 * inside the screen; on top of the page it travels to the screen's edge.
 * And it is a copy, not a second React mount: a remounted card would speak
 * its word again (auto-pronounce) and read its example again.
 *
 * Framework-free. Web Animations ignore the reduced-motion rule in
 * `styles/motion.css`, so every caller checks `reducedMotion()` itself.
 */

/** Marks every stand-in, so a page can find any left behind. */
export const COPY_ATTRIBUTE = 'data-swipe-copy';

/**
 * A flight removes its copy when it lands, and in any case this long after
 * it should have: an animation paused in a hidden tab, or a runtime that
 * never advances it, must not leave a card drawn over the page.
 */
const LANDING_GRACE_MS = 150;

/** At most this many cards in flight; a third finishes the oldest at once. */
export const MAX_GHOSTS = 2;

/** Whether this device asked for less motion. Read at each use: it can change mid-session. */
export function reducedMotion(): boolean {
  return (
    typeof window.matchMedia === 'function' && window.matchMedia('(prefers-reduced-motion: reduce)').matches
  );
}

/** Whether this browser can run Web Animations (happy-dom and very old web views cannot). */
export function canAnimate(element: Element): boolean {
  return typeof (element as HTMLElement & { animate?: unknown }).animate === 'function';
}

/** Room left around a copy for its shadow and its pill, on a side that is not cut. */
const OVERHANG_PX = 80;

/**
 * Copies `source` into `document.body` at the place it is drawn, with
 * `className` added (the module's stand-in style), inert and hidden from
 * assistive technology. Its scroll positions are copied too, so a long
 * answer scrolled halfway stays halfway. A card with no size (not laid out)
 * has nothing to draw, and gets no copy. With `seen`, the box the card is
 * seen through (a frame that scrolls a card too tall for it), the copy shows
 * only that part: lifted, it never grows what the screen was not showing.
 */
export function liftCopy(source: HTMLElement, className: string, seen?: DOMRect): HTMLElement | undefined {
  const box = source.getBoundingClientRect();
  if (box.width === 0 || box.height === 0) return undefined;
  const copy = source.cloneNode(true) as HTMLElement;
  copy.removeAttribute('id');
  for (const element of copy.querySelectorAll('[id]')) element.removeAttribute('id');
  copy.setAttribute('aria-hidden', 'true');
  copy.setAttribute(COPY_ATTRIBUTE, '');
  copy.setAttribute('inert', '');
  copy.classList.add(className);
  copy.style.left = `${String(box.left)}px`;
  copy.style.top = `${String(box.top)}px`;
  copy.style.width = `${String(box.width)}px`;
  copy.style.height = `${String(box.height)}px`;
  copy.style.opacity = '';
  if (seen !== undefined && seen.height > 0) {
    const top = seen.top - box.top;
    const bottom = box.bottom - seen.bottom;
    if (top > 0 || bottom > 0) {
      const edge = (cut: number): string => (cut > 0 ? `${String(cut)}px` : `${String(-OVERHANG_PX)}px`);
      copy.style.clipPath = `inset(${edge(top)} ${String(-OVERHANG_PX)}px ${edge(bottom)} ${String(-OVERHANG_PX)}px)`;
    }
  }
  document.body.append(copy);

  const from = [source, ...source.querySelectorAll<HTMLElement>('*')];
  const to = [copy, ...copy.querySelectorAll<HTMLElement>('*')];
  from.forEach((element, index) => {
    const twin = to[index];
    if (twin !== undefined && element.scrollTop > 0) twin.scrollTop = element.scrollTop;
  });
  return copy;
}

const flying: Animation[] = [];

/** A cancelled animation rejects its `finished` promise; nothing here waits on it. */
export function quiet(animation: Animation): void {
  void animation.finished.catch(() => undefined);
}

/** A copy in flight. */
export interface Flight {
  /**
   * Stops the flight where it is and hands the copy back, still on the page
   * and drawn at that place, for a finger that caught it mid-air. Neither the
   * landing nor its `onDone` happens.
   */
  catchIt(): void;
}

/**
 * Sends a copy on its way and removes it when it lands, then calls `onDone`.
 * Keeps at most `MAX_GHOSTS` in flight, so fast swiping never piles copies up.
 */
export function fly(
  copy: HTMLElement,
  keyframes: Keyframe[],
  options: KeyframeAnimationOptions,
  onDone?: () => void,
): Flight {
  if (!canAnimate(copy)) {
    copy.remove();
    onDone?.();
    return { catchIt: () => undefined };
  }
  while (flying.length >= MAX_GHOSTS) flying.shift()?.finish();
  const animation = copy.animate(keyframes, { fill: 'forwards', ...options });
  quiet(animation);
  flying.push(animation);
  let over = false;
  const forget = (): void => {
    over = true;
    window.clearTimeout(safety);
    const at = flying.indexOf(animation);
    if (at >= 0) flying.splice(at, 1);
  };
  const done = (): void => {
    if (over) return;
    forget();
    copy.remove();
    onDone?.();
  };
  const length = typeof options.duration === 'number' ? options.duration : 0;
  const safety = window.setTimeout(done, length + LANDING_GRACE_MS);
  animation.addEventListener('finish', done);
  animation.addEventListener('cancel', done);
  return {
    catchIt() {
      if (over) return;
      forget();
      const here = getComputedStyle(copy).transform;
      copy.style.transform = here === '' ? 'none' : here;
      copy.style.opacity = '';
      animation.cancel();
    },
  };
}

/** The x offset a copy is drawn at right now, mid-animation or not. */
export function currentOffset(element: HTMLElement): number {
  const transform = getComputedStyle(element).transform;
  if (transform === '' || transform === 'none') return 0;
  try {
    return new DOMMatrixReadOnly(transform).m41;
  } catch {
    return 0;
  }
}
