import { useEffect, useRef, useState } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { setReminder } from '@/db/mutations.js';
import { getMeta, setMeta } from '@/db/schema.js';
import markUrl from '@/features/intro/marks/lexpad-mark-v1.svg';
import { notificationsAllowedHere, reminderHour } from '@/features/session/reminderOffer.js';
import { startReminder } from '@/features/settings/reminders.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { localTimeZone } from '@/lib/format.js';
import { syncSoon } from '@/sync/store.js';
import { REMIND_RESULT_MS, reminderPreview } from './firstAsk.js';
import styles from './FirstReminderAsk.module.css';

/**
 * "We'll remind you before you forget." (onboarding v2 spec §4.11), in the
 * phone and desktop apps, right after the first word's celebration. Shown is asked:
 * `reminderAsked` is set as it appears, so the first summary's
 * `FirstReminder` never asks again; when the introduction's "When should I
 * remind you?" was already answered (on, or refused), it is not shown. "Turn on reminders" is the one moment
 * the phone's own permission dialog appears (Android 13+, iOS), through the
 * same calls Settings uses; "Not now" goes to Today and asks nothing.
 */
export function FirstReminderAsk({ onDone }: { onDone: () => void }): React.JSX.Element {
  const [time, setTime] = useState(() => reminderHour());
  const [result, setResult] = useState<'idle' | 'busy' | 'on' | 'denied'>('idle');
  const heading = useRef<HTMLHeadingElement>(null);
  const preview = reminderPreview(t('reminder.body'));

  // Answered in the introduction already (turned on, or refused by the
  // phone: `applyIntroChoices` marks it asked): straight on to Today. Only
  // "Not now" there leaves this ask its turn.
  const [askedBefore, setAskedBefore] = useState<boolean | undefined>(undefined);
  useEffect(() => {
    let live = true;
    void Promise.all([getMeta('reminderAsked').catch(() => false), notificationsAllowedHere()]).then(
      ([asked, allowed]) => {
        if (!live) return;
        // Notifications switched off in the desktop app: its own answer,
        // so nothing is asked and nothing is marked.
        const skip = asked || !allowed;
        setAskedBefore(skip);
        if (skip) onDone();
        else void setMeta('reminderAsked', true);
      },
    );
    return () => {
      live = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- once, as it opens
  }, []);
  useEffect(() => {
    if (askedBefore === false) heading.current?.focus({ preventScroll: true });
  }, [askedBefore]);

  useEffect(() => {
    if (result !== 'on' && result !== 'denied') return undefined;
    const timer = window.setTimeout(onDone, REMIND_RESULT_MS);
    return () => {
      window.clearTimeout(timer);
    };
  }, [result, onDone]);

  const turnOn = (): void => {
    setResult('busy');
    void (async () => {
      try {
        await setReminder(time, localTimeZone());
        void syncSoon();
        // Scheduling asks the phone for permission.
        const status = await startReminder();
        setResult(status === 'denied' ? 'denied' : 'on');
      } catch {
        setResult('idle');
      }
    })();
  };

  const answered = result === 'on' || result === 'denied';
  // Nothing drawn until it is known whether to ask at all.
  if (askedBefore !== false) return <main className={styles.screen} aria-busy="true" />;
  return (
    <main className={styles.screen}>
      <div className={styles.scroll}>
        <div className={styles.col}>
          <div className={styles.note} aria-hidden="true">
            <img className={styles.mark} src={markUrl} alt="" width={38} height={38} />
            <div className={styles.noteText}>
              <div className={styles.noteHead}>
                <span>{t('app.name')}</span>
                <span className={styles.noteTime}>{time}</span>
              </div>
              <div className={styles.noteTitle}>{preview.title}</div>
              <div className={styles.noteLine}>{preview.line}</div>
            </div>
          </div>
          <h1 ref={heading} className={styles.title} tabIndex={-1}>
            {t('onb.n.title')}
          </h1>
          <p className={styles.lead}>{t('onb.n.lead')}</p>
          <div className={styles.timeRow}>
            <span id="first-reminder-at">{t('onb.n.at')}</span>
            {/* The device's own time picker, as Settings → Notifications
                uses: the field lies over the chip, so a tap opens it. */}
            <label className={styles.timeChip}>
              <Icon name="clock" size={15} weight={2} />
              <span aria-hidden="true">{time}</span>
              <input
                type="time"
                className={styles.timeInput}
                value={time}
                disabled={result !== 'idle'}
                aria-label={t('onb.n.change', { time })}
                onChange={(event) => {
                  if (event.target.value !== '') setTime(event.target.value);
                }}
              />
            </label>
          </div>
          {answered && (
            <p className={styles.result} role="status">
              {result === 'on' ? t('intro.remindDone', { time }) : t('onb.n.denied')}
            </p>
          )}
        </div>
      </div>
      <div className={styles.foot}>
        <button
          type="button"
          className={cx(styles.primary, 'press')}
          disabled={result !== 'idle'}
          onClick={turnOn}
        >
          {t('onb.n.on')}
        </button>
        <button type="button" className={styles.quiet} disabled={answered} onClick={onDone}>
          {t('intro.remindLater')}
        </button>
      </div>
    </main>
  );
}
