import { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { MAX_BOX, type LanguageCode, type Word } from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { BoxMeter } from '@/components/ui/BoxMeter.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { setProgressFlags } from '@/db/mutations.js';
import { localTimeZone } from '@/lib/format.js';
import { syncSoon } from '@/sync/store.js';
import { shortDate } from '@/features/schedule/nextCheck.js';
import { STEP_HOW_PATH } from '@/features/learn/StepLink.js';
import type { WordMove } from './useSession.js';
import styles from './ComeBack.module.css';

/**
 * Up to this many words are named one by one; above it the summary counts
 * them and names the missed ones first, with "See all" for the rest. A
 * layout choice (owner, 2026-10-22): five rows fit a phone above Done.
 */
export const COME_BACK_LISTED = 5;

/** Missed words named in the folded view before "and N more". */
export const MISSED_NAMED = 3;

/**
 * "When they come back" on the session summary (app audit 2026-10-22,
 * owner-approved; it replaced "What happens next" and "Worth another look"):
 * each word the session answered, the missed ones first, with the day it
 * comes back and its step. A missed word can be starred on the spot, as
 * before. Worked out from the session's own answers, no read.
 */
export function ComeBack({
  moves,
  missed,
  today,
  langOf,
}: {
  moves: readonly WordMove[];
  missed: readonly Word[];
  today: number;
  /** The language each headword is written in (its own notebook's). */
  langOf: (word: Word) => LanguageCode;
}): React.JSX.Element | null {
  const [open, setOpen] = useState(false);
  if (moves.length === 0) return null;

  const missedIds = new Set(missed.map((word) => word.id));
  const ordered = [
    ...moves.filter((move) => missedIds.has(move.word.id)),
    ...moves.filter((move) => !missedIds.has(move.word.id)),
  ];
  const folded = ordered.length > COME_BACK_LISTED && !open;
  const backToday = moves.filter((move) => !move.kept && move.dueDay <= today).length;
  const missedMoves = ordered.filter((move) => missedIds.has(move.word.id));
  const named = folded ? missedMoves.slice(0, MISSED_NAMED) : ordered;
  const notNamedMissed = missedMoves.length - named.length;

  return (
    <section className={styles.section} aria-labelledby="come-back-title">
      <h2 id="come-back-title" className={styles.title}>
        {t('summary.comeBackTitle')}
      </h2>
      <div className={styles.card}>
        {/* How many moved up is the summary's own progress line; here, what comes back today. */}
        {folded && backToday > 0 && (
          <div className={styles.counts}>
            <p className={styles.count}>{t('summary.comeBackToday', { count: backToday })}</p>
          </div>
        )}
        {named.length > 0 && (
          <ul className={styles.list}>
            {named.map((move) => (
              <Row
                key={move.word.id}
                move={move}
                missed={missedIds.has(move.word.id)}
                today={today}
                lang={langOf(move.word)}
              />
            ))}
          </ul>
        )}
        {folded && notNamedMissed > 0 && (
          <p className={styles.more}>{t('summary.andMoreMissed', { count: notNamedMissed })}</p>
        )}
        {folded && (
          <button
            type="button"
            className={styles.seeAll}
            aria-expanded={false}
            onClick={() => {
              setOpen(true);
            }}
          >
            {t('summary.seeAll', { count: ordered.length })}
            <Icon name="chevronDown" size={15} weight={2.2} />
          </button>
        )}
        <p className={styles.foot}>
          <span>{t('summary.nextLine')}</span>{' '}
          <Link to={STEP_HOW_PATH} className={styles.how}>
            {t('summary.nextHow')}
          </Link>
        </p>
      </div>
    </section>
  );
}

/** When a word comes back, in the fewest words: "Later today", "Tomorrow", "Sun 25 Oct". */
function whenOf(move: WordMove, today: number): string {
  const days = move.dueDay - today;
  if (days <= 0) return t('summary.whenToday');
  if (days === 1) return t('summary.whenTomorrow');
  return shortDate(move.dueDay);
}

function Row({
  move,
  missed,
  today,
  lang,
}: {
  move: WordMove;
  missed: boolean;
  today: number;
  lang: LanguageCode;
}): React.JSX.Element {
  const navigate = useNavigate();
  const [starred, setStarred] = useState(move.word.progress?.starred === true);
  const step = Math.min(Math.max(move.to, 1), MAX_BOX);
  return (
    <li className={cx(styles.row, missed && styles.rowMissed)}>
      <button
        type="button"
        className={styles.open}
        onClick={() => {
          void navigate(`/words/${move.word.id}`);
        }}
      >
        <span className={styles.word}>
          <Bilingual lang={lang}>{move.word.headword}</Bilingual>
          {missed && <span className={styles.missedTag}>{t('summary.missedTag')}</span>}
        </span>
        <span className={styles.when}>
          {/* Drawn, not read: the words beside it say the step. */}
          <span aria-hidden="true" className={styles.meter}>
            <BoxMeter box={step} />
          </span>
          <span>{t('summary.whenRow', { when: whenOf(move, today), box: step, total: MAX_BOX })}</span>
        </span>
      </button>
      {missed && (
        <button
          type="button"
          className={cx(styles.star, starred && styles.starOn)}
          aria-label={starred ? t('action.unstar') : t('action.star')}
          aria-pressed={starred}
          onClick={() => {
            const next = !starred;
            setStarred(next);
            void setProgressFlags(move.word.id, { starred: next }, localTimeZone()).then(() => syncSoon());
          }}
        >
          <Icon name={starred ? 'starOn' : 'star'} size={18} />
        </button>
      )}
    </li>
  );
}
