const DECKS: readonly Deck[] = [
  'daily',
  'audio',
  'starred',
  'struggling',
  'confusables',
  'tricky',
  'notebook',
  'group',
  'mine',
  'level',
  'topic',
  'kind',
];

function deckFrom(value: string | null): Deck {
  return DECKS.find((deck) => deck === value) ?? 'daily';
}

/**
 * The languages and preferences a session needs, read from local data.
 *
 * A session may draw from more than one notebook, and a card written in
 * German must not be read out in English, so the languages are looked up
 * per card rather than fixed once. The notebook being shown is the
 * fallback for a card whose own notebook has gone.
 */
async function loadContext(): Promise<{
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  autoSpeak: boolean;
  speakExamples: boolean;
  /** Whether this client shows the SRS v2 screens (meta `srs`). */
  srs: boolean;
  /** Settings → Practice → "After an answer", on this device. */
  afterAnswer: AfterAnswer;
  /** Swipe to answer on this device: the switch and the coach's progress. Null until read. */
  swipe: StoredSwipe | null;
  byNotebook: Record<string, { targetLang: LanguageCode; meaningLang: LanguageCode }>;
}> {
  const [notebook, settings, all, srs, afterAnswer, swipe] = await Promise.all([
    getActiveNotebook(),
    loadSettings(),
    listNotebooks(),
    getMeta('srs'),
    loadAfterAnswer(),
    loadSwipe(),
  ]);
  return {
    targetLang: notebook?.targetLang ?? 'en',
    meaningLang: notebook?.meaningLang ?? 'fa',
    autoSpeak: settings?.autoSpeak ?? false,
    speakExamples: settings?.speakExamples ?? false,
    srs: srs?.state?.enabled === true,
    afterAnswer,
    swipe,
    byNotebook: Object.fromEntries(
      all.map((one) => [one.id, { targetLang: one.targetLang, meaningLang: one.meaningLang }]),
    ),
  };
}

/**
 * A graded flashcard still face down after this long turns to its answer:
 * longer than any flight home (`--dur-settle`, 240 ms), so it never cuts one
 * short, and soon enough that the miss's answer is never lost.
 */
const GRADED_FACE_DOWN_MS = 400;

/** The coach's demo waits for the answer side to settle in (its 220 ms entrance) and a breath more. */
const COACH_DEMO_DELAY_MS = 520;

const DEFAULT_CONTEXT = {
  targetLang: 'en' as LanguageCode,
  meaningLang: 'fa' as LanguageCode,
  autoSpeak: false,
  speakExamples: false,
  srs: false,
  afterAnswer: AFTER_ANSWER_DEFAULT,
  swipe: null as StoredSwipe | null,
  byNotebook: {} as Record<string, { targetLang: LanguageCode; meaningLang: LanguageCode }>,
};

/**
 * The practice session. `deck=first` is onboarding v2's three quick cards of
 * the learner's first word (FirstPractice); every other deck is the session.
 */
export function Session(): React.JSX.Element {
  const [params] = useSearchParams();
  return params.get('deck') === FIRST_DECK ? <FirstPractice /> : <DeckSession />;
}

/**
 * The practice session: one card at a time, graded by pointer, keyboard or
 * swipe. It owns the whole viewport, with no tab bar to press by accident.
 */
function DeckSession(): React.JSX.Element {
  const [params] = useSearchParams();
  const navigate = useNavigate();
  const deck = deckFrom(params.get('deck'));
  // Memoised: a fresh array on every render would rebuild the queue on
  // every render, and the queue is what the render is showing.
  const groupIds = useMemo(() => params.get('ids')?.split(',').filter(Boolean), [params]);
  // A token the summary's "Keep going" puts in the address to ask for this
  // deck again. It rides into the shuffle seed, so a second run of the same
  // deck is not the same run twice.
  const again = params.get('again') ?? '';
  // What a level, topic or kind deck practises; read once per URL.
  const scope = useMemo<DeckScope>(() => {
    const level = params.get('level');
    const topic = params.get('topic');
    const kind = params.get('kind');
    return {
      ...(level ? { level } : {}),
      ...(topic ? { topic } : {}),
      ...(kind && (KINDS as readonly string[]).includes(kind) ? { kind: kind as Kind } : {}),
    };
  }, [params]);

  const context = useLiveQuery(loadContext, DEFAULT_CONTEXT, []);
  // Which notebooks this session draws from. It rides in the address, so
  // the choice survives a reload and the back button, and Today decides it
  // from the setting before sending anybody here.
  const across: PracticeScope = params.get('scope') === 'all' ? 'all' : 'notebook';
  const { state, answer, answerTyped, answerChoice, next, undo, toggleStar, saveNote } = useSession(
    deck,
    groupIds,
    scope,
    across,
    again,
    context.afterAnswer,
  );
  const { card, outcome, boxAfter, practised } = state;

  const [flipped, setFlipped] = useState(false);
  /** A finger (or the mouse) holds the card: timers wait for it. */
  const [dragging, setDragging] = useState(false);
  const [noteOpen, setNoteOpen] = useState(false);
  const [detailOpen, setDetailOpen] = useState(false);
  const [typed, setTyped] = useState('');
  // A spelling card keeps its prompt, input and Check above the keyboard.
  const frame = useRef<HTMLElement>(null);
  const keyboard = useSoftKeyboard(frame);

  const leave = useCallback((): void => {
    void navigate('/', { replace: true });
  }, [navigate]);

  /**
   * A good session is a moment the phone apps may hand to the store's rating
   * dialog (`features/review`), never from the summary itself: only once
   * Today or the notebook is on screen with nothing open. It is noted as the
   * summary appears, so every way off it keeps it: Done, "Add another word"
   * (the notebook's add sheet asks as it closes), "Keep going", Android's
   * back. Until 2026-10-18 only Done noted it, and the other ways lost it.
   * The summary going away is a calm point too; Done is the usual one.
   */
  const finishedSummary = state.status === 'finished' ? state.summary : undefined;
  useEffect(() => {
    if (finishedSummary === undefined) return undefined;
    noteSession({
      reviewed: finishedSummary.reviewed,
      correct: finishedSummary.correct,
      mastered: finishedSummary.mastered.length,
      streakBefore: finishedSummary.streakBefore,
      streak: finishedSummary.streak,
    });
    return () => {
      askWhenCalm();
    };
  }, [finishedSummary]);
  const leaveSummary = leave;

  const swipe = useRef<SwipeHandle>(null);
  const knewSide = useKnewSide();
  useNoSideScrollBack();
  const flipCard = card !== undefined && !isChoice(card.type) && !isTyped(card.type);
  // On unless this device turned it off: the default, also before the first
  // read lands (the coach waits for the read; a swipe need not).
  const swipeOn = context.swipe?.off !== true;

  // Which card was last sent on, so a timer, a key and a tap landing
  // together move the session one card, never two.
  const advancedFrom = useRef<string | undefined>(undefined);
  /** The answer being recorded; the session moves on only once it is. */
  const pending = useRef<Promise<void>>(Promise.resolve());
  /** The card that last left, and which way, for Undo to bring it back from that side. */
  const lastLeft = useRef<{ dir: Direction; flip: boolean } | undefined>(undefined);
  /** Set by Undo when the card it brought back should slide in from the side it left by. */
  const returning = useRef<Direction | undefined>(undefined);
  /** A card answered from its front by a swipe turns once it is home, never on the way. */
  const turnOnLanding = useRef(false);
  /**
   * The card last skipped as known from its front, said with its Undo under
   * the next card while that Undo lasts (review M3: a skip with a key, or
   * under reduced motion, was otherwise silent).
   */
  const [skipped, setSkipped] = useState<{ headword: string; notebookId: string } | undefined>(undefined);

  const grade = useCallback(
    (correct: boolean): void => {
      pending.current = answer(correct);
    },
    [answer],
  );

  /**
   * Advances and puts the next card face down.
   *
   * The card on screen leaves towards the side of its answer (`dir`, else
   * Knew it's side for a right answer and the other for a miss): thrown
   * from where a swipe let it go, or sliding off after a button, a key or a
   * timer, while the next card enters under it, so no time is added. A
   * choice or spelling card leaves that way only when swiped on.
   *
   * The typed answer is cleared here too. It used to survive into the next
   * card, so somebody who spelled one word found it already filled in on
   * the following one — and could grade a card against the previous word's
   * letters without noticing.
   */
  const advance = useCallback(
    (dir?: Direction, label?: SwipeLabel): void => {
      const from = card?.key;
      if (from !== undefined && advancedFrom.current === from) return;
      advancedFrom.current = from;
      const side: Direction = dir ?? (outcome === 'wrong' ? (-knewSide as Direction) : knewSide);
      if (flipCard || dir !== undefined) swipe.current?.leave(side, label);
      lastLeft.current = { dir: side, flip: flipCard };
      // A swipe can outrun the write of its own answer by a few
      // milliseconds; the session moves on once it is recorded.
      turnOnLanding.current = false;
      void pending.current.then(() => {
        setFlipped(false);
        setTyped('');
        next();
      });
    },
    [next, card?.key, outcome, knewSide, flipCard],
  );

  /**
   * Answered from the front, before it was turned (a swipe or ← →). Known:
   * the card is gone at once and the next one is up, which is what a learner
   * who knows a word wants (owner, 25 Oct 2026); Undo on the next card
   * brings it back face up. Not known: it turns to its answer, which the
   * learner needs to see, and waits as a miss does. A learner who waits
   * after every answer gets the turn in both cases.
   */
  const answerFromFront = useCallback(
    (knew: boolean, dir: Direction, by: 'swipe' | 'key'): void => {
      if (!card || outcome !== undefined) return;
      if (knew && !waitsForNext(context.afterAnswer, 'correct')) {
        grade(true);
        setSkipped({ headword: card.word.headword, notebookId: card.word.notebookId });
        // A key has no thrown card to say it: the leaving one carries the pill.
        advance(dir, by === 'key' ? 'knew' : undefined);
        return;
      }
      grade(knew);
      if (by === 'swipe') turnOnLanding.current = true;
      else setFlipped(true);
    },
    [card, grade, advance, outcome, context.afterAnswer],
  );

  // Never a graded flashcard face down: if anything ever kept its turn from
  // happening (a card caught on its way home), it turns once nothing holds it
  // (round 2 review R1). The answer is the point of a miss.
  const faceDownGraded = flipCard && !flipped && outcome !== undefined && !dragging;
  useEffect(() => {
    if (!faceDownGraded) return undefined;
    const timer = window.setTimeout(() => {
      turnOnLanding.current = false;
      setFlipped(true);
    }, GRADED_FACE_DOWN_MS);
    return () => {
      window.clearTimeout(timer);
    };
  }, [faceDownGraded, card?.key]);

  /** A swiped card that stayed is home: a front answered by the swipe turns now. */
  const onLanded = useCallback((): void => {
    if (!turnOnLanding.current) return;
    turnOnLanding.current = false;
    setFlipped(true);
  }, []);

  /** A swipe let go past the point (spec §1's table). */
  const onSwipe = useCallback(
    (dir: Direction): void => {
      if (!card) return;
      if (outcome !== undefined) {
        // An answered card: either way is Next.
        advance(dir);
        return;
      }
      if (!flipCard) return;
      const knew = dir === knewSide;
      void noteSwiped(!flipped);
      if (!flipped) {
        answerFromFront(knew, dir, 'swipe');
        return;
      }
      grade(knew);
      // From the back, a right answer is thrown and the next card is there
      // at once; a miss (or a learner who waits after every answer) stays.
      if (knew && !waitsForNext(context.afterAnswer, 'correct')) advance(dir);
    },
    [card, outcome, flipCard, knewSide, flipped, answerFromFront, grade, advance, context.afterAnswer],
  );

  // The latest undo, for a press that had to wait for its answer to be recorded.
  const latestUndo = useRef(undo);
  useLayoutEffect(() => {
    latestUndo.current = undo;
  });

  /**
   * Undo, bringing a card that already left back to the screen, face up. An
   * answer is recorded a few milliseconds after it is given; an Undo pressed
   * in between waits for it (and for the screen to catch up), or it found
   * nothing to take back.
   */
  const takeBack = useCallback(async (): Promise<void> => {
    swipe.current?.stopDemo();
    await pending.current;
    await new Promise((resolve) => setTimeout(resolve, 0));
    const where = await latestUndo.current();
    setSkipped(undefined);
    if (where !== 'back') return;
    advancedFrom.current = undefined;
    const leftBy = lastLeft.current;
    returning.current = leftBy?.dir;
    // It has been seen: the honest choice is between the two grades again.
    setFlipped(leftBy?.flip === true);
  }, []);

  // A card Undo brought back slides in from the side it left by.
  useLayoutEffect(() => {
    const dir = returning.current;
    if (dir === undefined) return;
    returning.current = undefined;
    swipe.current?.returnFrom(dir);
  }, [card?.key]);

  // The new learner's journey (SRS v2): one quiet line on a card at three
  // moments — under the first flips, at the first miss, at the first answer
  // kept as practice. Never a modal, never while typing.
  const showsKeys = useShowsKeys();
  // The swipe coach (spec §9): its own lesson, not a tip, once per run.
  const [coachRun, setCoachRun] = useState<CoachRun>({});
  const coachWanted: CoachStep | null =
    card === undefined || !swipeOn
      ? null
      : coachStep(context.swipe, coachRun, {
          key: card.key,
          flip: flipCard,
          flipped,
          graded: outcome !== undefined,
          showsKeys,
        });
  // The demo and the line under the first flips ("Be honest…") never share
  // a card, and each keeps its turn: the very first demo takes the first
  // turned card (the line follows on the next one); after that the line,
  // which is shown only in the first sessions, goes first, and the demo
  // comes back in the sessions after them.
  const firstDemo =
    coachWanted === 'back' &&
    card !== undefined &&
    (coachRun.backOn === card.key || (context.swipe?.backDemos ?? 0) === 0);
  const { tip, firstGradeDue } = useCardTip(state, flipped, firstDemo);
  const coach: CoachStep | null = coachWanted === 'back' && !firstDemo && firstGradeDue ? null : coachWanted;
  // The run remembers which card each step showed on, as the step appears
  // (React's adjust-state-while-rendering: no render shows it unmarked).
  const coachKey = card?.key;
  if (coach === 'back' && coachKey !== undefined && coachRun.backOn !== coachKey) {
    setCoachRun({ ...coachRun, backOn: coachKey });
  }
  if (coach === 'front' && coachKey !== undefined && coachRun.frontOn !== coachKey) {
    setCoachRun({ ...coachRun, frontOn: coachKey });
  }
  // Each step counts once per run on this device, as it shows.
  useEffect(() => {
    if (coachRun.backOn !== undefined) void noteCoach('back');
  }, [coachRun.backOn]);
  useEffect(() => {
    if (coachRun.frontOn !== undefined) void noteCoach('front');
  }, [coachRun.frontOn]);
  // The demo, once the answer has settled in, unless the card is answered first.
  useEffect(() => {
    if (coach !== 'back' || reducedMotion()) return undefined;
    const timer = window.setTimeout(() => {
      swipe.current?.demo();
    }, COACH_DEMO_DELAY_MS);
    return () => {
      window.clearTimeout(timer);
    };
  }, [coach, coachKey]);

  // The first miss of a session grows the counter ("1 of 3" becomes "1 of
  // 4"); one line says why, once, on the card that was missed (app audit
  // 2026-10-22). A tip about the same miss wins the place.
  const lastTotal = useRef(0);
  const missSaid = useRef(false);
  const [missOn, setMissOn] = useState<string | undefined>(undefined);
  useEffect(() => {
    const before = lastTotal.current;
    lastTotal.current = state.total;
    if (before > 0 && state.total > before && !missSaid.current && card !== undefined) {
      missSaid.current = true;
      setMissOn(card.key);
    }
  }, [state.total, card]);

  // A graded card moves on by itself, so the rhythm of a session holds
  // without the learner having to press anything -- unless the learner's
  // "After an answer" says it waits for Next, which after a mistake it does
  // by default (pace.ts): the right answer stays until they have read it. A
  // line said about this answer gets the time to be read.
  const delay =
    outcome === undefined ? null : sessionAdvanceMs(context.afterAnswer, outcome, tip !== undefined);
  const waiting = outcome !== undefined && delay === null;
  useEffect(() => {
    // A card held by a finger waits; let go short of the point, it starts again.
    if (delay === null || dragging) return;
    const timer = window.setTimeout(() => {
      advance();
    }, delay);
    return () => {
      window.clearTimeout(timer);
    };
  }, [delay, advance, dragging]);

  // A card that waits puts the keyboard and the screen reader on Next, so
  // Enter or Space goes on and the button is announced.
  const nextButton = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    if (waiting) nextButton.current?.focus({ preventScroll: true });
  }, [waiting, card?.key]);

  // The prototype's keys: space flips, arrows grade, 1 to 4 pick, Enter
  // continues, S stars, Escape closes.
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent): void => {
      if (noteOpen || detailOpen) return;
      const target = event.target;
      const gradeKey = event.key === 'ArrowLeft' || event.key === 'ArrowRight';
      // A held key never answers one card after another.
      if (event.repeat && (gradeKey || event.key === ' ' || event.key === 'Enter')) {
        if (!(target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement))
          event.preventDefault();
        return;
      }
      const typing = target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement;

      if (event.key === 'Escape') {
        leave();
        return;
      }

      // Enter submits the spelling drill from inside the field, which is
      // where the hands already are.
      if (typing && event.key === 'Enter' && card && isTyped(card.type)) {
        event.preventDefault();
        if (outcome === undefined) void answerTyped(typed);
        else advance();
        return;
      }
      if (typing) return;

      if (event.key === 's' || event.key === 'S') {
        event.preventDefault();
        void toggleStar();
        return;
      }
      // Z or Backspace takes the last answer back while its Undo is offered
      // (or the answer on screen, a moment before its Undo appears).
      const plain = !event.metaKey && !event.ctrlKey && !event.altKey;
      if (
        plain &&
        (event.key === 'z' || event.key === 'Z' || event.key === 'Backspace') &&
        (state.canUndo || outcome !== undefined)
      ) {
        event.preventDefault();
        void takeBack();
        return;
      }
      if (!card) return;
      swipe.current?.stopDemo();
      // The arrow on the Knew it side (the right on a left-to-right page).
      const keyDir: Direction = event.key === 'ArrowRight' ? 1 : -1;

      // ← or → on an answered card goes on, leaving that way.
      if (gradeKey && outcome !== undefined) {
        event.preventDefault();
        advance(keyDir);
        return;
      }

      // Enter or Space goes on from an answered card -- but a key on another
      // control (Undo, the star, a sheet's button) is that control's.
      if ((event.key === 'Enter' || event.key === ' ') && outcome !== undefined) {
        const onOther =
          target instanceof Element &&
          target !== nextButton.current &&
          target.closest('button, a, select, [role="slider"]') !== null;
        if (onOther) return;
        event.preventDefault();
        advance();
        return;
      }
      if (isChoice(card.type)) {
        const index = Number.parseInt(event.key, 10) - 1;
        const option = card.options?.[index];
        if (option && outcome === undefined) {
          event.preventDefault();
          void answerChoice(option);
        }
        return;
      }
      if (isTyped(card.type)) return;

      if (event.key === ' ') {
        event.preventDefault();
        setFlipped(true);
        return;
      }
      if (outcome === undefined && gradeKey) {
        event.preventDefault();
        // From the front too, as the card's own hint has always said.
        if (flipped) grade(keyDir === knewSide);
        else answerFromFront(keyDir === knewSide, keyDir, 'key');
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
    };
  }, [
    advance,
    answerChoice,
    answerTyped,
    card,
    detailOpen,
    flipped,
    grade,
    answerFromFront,
    knewSide,
    leave,
    noteOpen,
    outcome,
    toggleStar,
    typed,
    state.canUndo,
    takeBack,
  ]);

  if (state.status === 'loading') {
    return (
      <Screen full>
        <Spinner />
      </Screen>
    );
  }

  if (state.status === 'empty') {
    return (
      <Screen full>
        <EmptyState
          middle
          icon="check"
          title={t('session.clearTitle')}
          body={t('today.nothingDue')}
          actions={<Button onClick={leave}>{t('action.done')}</Button>}
        />
      </Screen>
    );
  }

  if (state.status === 'finished' || !card) {
    return (
      <Summary
        summary={state.summary}
        context={context}
        onDone={leaveSummary}
        deck={deck}
        remaining={state.remaining}
        srs={context.srs}
      />
    );
  }

  const progress = state.total === 0 ? 0 : (state.done / state.total) * 100;
  // Said while its Undo lasts, and only for the answer Undo would take back.
  const skippedShown =
    skipped !== undefined &&
    state.canUndo &&
    state.lastAnswer?.correct === true &&
    state.lastAnswer.headword === skipped.headword &&
    outcome === undefined
      ? skipped
      : undefined;
  const swipeMode: SwipeMode =
    !swipeOn || noteOpen || detailOpen
      ? 'off'
      : outcome !== undefined
        ? 'next'
        : flipCard
          ? 'grade'
          : 'rubber';
  const keyLabel = (label: string): React.JSX.Element | null =>
    showsKeys ? (
      <kbd className={styles.key} aria-hidden="true">
        {label}
      </kbd>
    ) : null;
  // The keys on the Knew it and Didn't know sides, in this page's direction.
  const knewKey = knewSide === 1 ? 'ArrowRight' : 'ArrowLeft';
  const missKey = knewSide === 1 ? 'ArrowLeft' : 'ArrowRight';
  const knewGlyph = t(knewSide === 1 ? 'session.keyRight' : 'session.keyLeft');
  const missGlyph = t(knewSide === 1 ? 'session.keyLeft' : 'session.keyRight');
  // This card's own languages. A session may draw from more than one
  // notebook, and a German word must not be shown right-to-left or read
  // out in English because the notebook on screen happens to be Persian.
  const languages = context.byNotebook[card.word.notebookId] ?? context;
  const starred = card.word.progress?.starred === true;
  const hasCorrection = (card.word.correction ?? '') !== '';
  // A deck other than the day's plan is extra practice. When the card's
  // notebook keeps extra practice out of the schedule, a word that is not
  // due yet keeps its box, and the session says so up front (SRS v2) --
  // only when the deck has such a word: on a deck of due words every answer
  // counts, and the line read as if none would.
  const extraPractice =
    context.srs &&
    deck !== 'daily' &&
    state.schedules[card.word.notebookId]?.extraPractice === 'keep' &&
    state.notDue.has(card.word.notebookId);

  return (
    <main ref={frame} className={styles.screen} {...keyboardAttributes(keyboard)}>
      <h1 className="sr-only">{t('session.heading')}</h1>
      <div className={styles.topBar}>
        <button type="button" className={styles.close} onClick={leave} aria-label={t('action.close')}>
          <Icon name="close" size={18} weight={2} />
        </button>
        <div
          className={styles.track}
          role="progressbar"
          aria-valuenow={state.done}
          aria-valuemax={state.total}
          aria-label={t('session.progress', { done: state.done, total: state.total })}
        >
          <div className={styles.fill} style={{ width: `${String(progress)}%` }} />
        </div>
        <span className={styles.counter}>
          {t('session.counter', { n: state.index + 1, total: state.total })}
        </span>
      </div>

      <div className={styles.meta}>
        {/* One row (app audit 2026-10-22): what the card is on the start
            side, the star and "⋯" on the end side. It was two rows, the
            second three unlabelled icons. */}
        <div className={styles.metaRow}>
          {/* Chips rather than a run-on sentence: three unrelated facts joined
            by middots read as one long label and none of them was legible
            at a glance. */}
          <span className={styles.metaChips}>
            <span className={cx(styles.chip, styles.chipKind)}>{typeLabel(card.type)}</span>
            {/* The ladder, made visible. Until the card is graded it shows the
              rung the word is on; the moment it is, it moves to the rung the
              word landed on and the new bar lights. This is the model the
              whole app runs on and it used to happen entirely out of sight. */}
            <BoxMeter
              key={boxAfter === undefined ? 'box' : `box-${String(boxAfter)}`}
              box={boxAfter ?? card.box}
              rung={boxAfter !== undefined && boxAfter > card.box}
              className={cx(
                styles.boxChip,
                boxAfter !== undefined && boxAfter > card.box && styles.boxUp,
                boxAfter !== undefined && boxAfter < card.box && styles.boxBack,
              )}
            />
            {/* Practice only: the box did not move, so nothing claims a rung.
              The tag is the whole feedback, and it is read out. */}
            {practised && (
              <span className={cx(styles.tag, styles.tagPractice)} role="status">
                <span className={styles.dot} />
                {t('schedule.practiceTag')}
              </span>
            )}
            {card.isNew && (
              <span className={cx(styles.tag, styles.tagNew)}>
                <span className={styles.dot} />
                {t('session.new')}
              </span>
            )}
            {hasCorrection && (
              <span className={cx(styles.tag, styles.tagCorrection)}>
                <span className={styles.dot} />
                {t('session.correction')}
              </span>
            )}
          </span>
          <div className={styles.metaActions}>
            <div className={styles.undoSlot}>
              {state.canUndo && (
                <button
                  type="button"
                  className={styles.undo}
                  aria-keyshortcuts="Z Backspace"
                  aria-label={
                    state.lastAnswer === undefined
                      ? undefined
                      : t('session.undoAnswer', { word: state.lastAnswer.headword })
                  }
                  onClick={() => {
                    void takeBack();
                  }}
                >
                  <Icon name="undo" size={14} weight={2} />
                  {t('action.undo')}
                  {keyLabel(t('session.keyUndo'))}
                </button>
              )}
            </div>
            <button
              type="button"
              className={cx(styles.metaButton, styles.starButton, starred && styles.starOn)}
              aria-label={starred ? t('action.unstar') : t('session.starWord')}
              aria-pressed={starred}
              onClick={() => {
                void toggleStar();
              }}
            >
              <Icon name={starred ? 'starOn' : 'star'} size={20} />
            </button>
            <SessionMenu
              onNote={() => {
                setNoteOpen(true);
              }}
              onDetails={() => {
                setDetailOpen(true);
              }}
            />
          </div>
        </div>
        {extraPractice && <p className={styles.deckLine}>{t('schedule.deckLine')}</p>}
      </div>

      {/* What this card is asking, as a heading above it. It used to sit
          under the answers as grey hint text, which is where nobody looks
          first and the last place an instruction should be. */}
      <h1 className={styles.ask}>{askFor(card.type)}</h1>

      <div className={styles.stage}>
        <SwipeCard
          ref={swipe}
          host={frame}
          frameClassName={styles.cardFrame}
          cardKey={card.key}
          flip={flipCard}
          face={flipped ? 'back' : 'front'}
          knewSide={knewSide}
          mode={swipeMode}
          onCommit={onSwipe}
          onLanded={onLanded}
          onDrag={setDragging}
        >
          {isTyped(card.type) ? (
            <SpellCard
              key={card.key}
              card={card}
              targetLang={languages.targetLang}
              meaningLang={languages.meaningLang}
              outcome={outcome}
              revealed={state.revealed}
              typed={typed}
              onType={setTyped}
              alt={state.index % 2 === 1}
            />
          ) : isChoice(card.type) ? (
            <ChoiceCard
              key={card.key}
              card={card}
              targetLang={languages.targetLang}
              meaningLang={languages.meaningLang}
              outcome={outcome}
              autoSpeak={context.autoSpeak}
              onChoose={(option) => {
                pending.current = answerChoice(option);
              }}
              alt={state.index % 2 === 1}
            />
          ) : (
            <FlipCard
              key={card.key}
              card={card}
              targetLang={languages.targetLang}
              meaningLang={languages.meaningLang}
              autoSpeak={context.autoSpeak}
              speakExamples={context.speakExamples}
              flipped={flipped}
              swipe={swipeOn}
              onFlip={() => {
                setFlipped(true);
              }}
              onEditMemo={() => {
                setNoteOpen(true);
              }}
              alt={state.index % 2 === 1}
            />
          )}
        </SwipeCard>
      </div>

      <div className={styles.actions}>
        {/* Above the buttons, which stay where they are: the action row grows
            upward into the stage. Read out by the status line below. */}
        {skippedShown !== undefined ? (
          // The card skipped as known, by name, with its Undo where the
          // thumb is (review M3); it goes with the Undo's window.
          <p className={styles.skipLine} role="status">
            <Icon name="check" size={16} weight={2.4} className={styles.skipMark} />
            <span className={styles.skipWords}>
              {t('swipe.skipped')}{' '}
              <Bilingual lang={(context.byNotebook[skippedShown.notebookId] ?? context).targetLang}>
                {skippedShown.headword}
              </Bilingual>
            </span>
            <button
              type="button"
              className={styles.skipUndo}
              aria-label={t('session.undoAnswer', { word: skippedShown.headword })}
              onClick={() => {
                void takeBack();
              }}
            >
              {t('action.undo')}
            </button>
          </p>
        ) : coach !== null ? (
          <p className={styles.tipLine} aria-hidden="true">
            {coach === 'back'
              ? t('swipe.coachBack')
              : t('swipe.coachFront', { side: t(knewSide === 1 ? 'swipe.right' : 'swipe.left') })}
          </p>
        ) : (
          tip !== undefined && (
            <p className={styles.tipLine} aria-hidden="true">
              {t(`tip.${tip}`)}
            </p>
          )
        )}
        {coach === null && tip === undefined && missOn !== undefined && missOn === card.key && (
          <p className={styles.tipLine} role="status">
            {t('session.missedBack')}
          </p>
        )}
        {/* Keyed with the card so the buttons arrive with it, not ahead of it. */}
        <div key={card.key} className={cx(styles.actionsIn, state.index % 2 === 1 && styles.actionsInB)}>
          {isTyped(card.type) ? (
            <button
              ref={nextButton}
              type="button"
              className={cx(styles.primary, styles.accent, outcome !== undefined && styles.nextButton)}
              disabled={typed.trim() === '' && outcome === undefined}
              aria-keyshortcuts="Enter"
              onClick={() => {
                if (outcome === undefined) pending.current = answerTyped(typed);
                else advance();
              }}
            >
              {outcome === undefined ? t('session.check') : t('session.next')}
              {keyLabel(t('session.keyEnter'))}
            </button>
          ) : isChoice(card.type) ? (
            outcome === undefined ? (
              // The instruction is the heading above the card now.
              <div className={styles.hint} />
            ) : outcome === 'wrong' || waiting ? (
              // A wrong pick reveals the answer, and the learner decides when
              // they have read it (or, moving on by itself, can go sooner);
              // a right one moves on by itself unless they chose to wait.
              <button
                ref={nextButton}
                type="button"
                className={cx(styles.primary, styles.nextButton)}
                aria-keyshortcuts="Enter"
                onClick={() => {
                  advance();
                }}
              >
                {t('session.next')}
                {keyLabel(t('session.keyEnter'))}
              </button>
            ) : (
              <div className={styles.hint} />
            )
          ) : waiting ? (
            // A graded flashcard that waits: Next takes the two grade
            // buttons' place, in the same row, at the same height.
            <button
              ref={nextButton}
              type="button"
              className={cx(styles.primary, styles.nextButton)}
              aria-keyshortcuts="Enter"
              onClick={() => {
                advance();
              }}
            >
              {t('session.next')}
              {keyLabel(t('session.keyEnter'))}
            </button>
          ) : !flipped ? (
            <button
              type="button"
              className={cx(styles.primary, styles.showAnswer)}
              aria-keyshortcuts="Space"
              onClick={() => {
                setFlipped(true);
              }}
            >
              {t('session.showAnswer')}
              {keyLabel(t('session.keySpace'))}
            </button>
          ) : (
            // After a grade the two buttons stay where they were, the chosen
            // one filled in, until the next card takes their place. Nothing
            // new appears in between, as the prototype has it.
            <div className={styles.grade}>
              <button
                type="button"
                className={cx(
                  styles.wrong,
                  outcome === 'wrong' && styles.gradePicked,
                  outcome === 'correct' && styles.gradePassed,
                )}
                disabled={outcome !== undefined}
                aria-keyshortcuts={missKey}
                onClick={() => {
                  swipe.current?.stopDemo();
                  grade(false);
                }}
              >
                {t('session.didntKnow')}
                {keyLabel(missGlyph)}
              </button>
              <button
                type="button"
                className={cx(
                  styles.right,
                  outcome === 'correct' && styles.gradePicked,
                  outcome === 'wrong' && styles.gradePassed,
                )}
                disabled={outcome !== undefined}
                aria-keyshortcuts={knewKey}
                onClick={() => {
                  swipe.current?.stopDemo();
                  grade(true);
                }}
              >
                {t('session.knewIt')}
                {keyLabel(knewGlyph)}
              </button>
            </div>
          )}
        </div>
      </div>

      <p className="sr-only" role="status" aria-live="polite">
        {[
          outcome === 'correct'
            ? t('session.correct')
            : outcome === 'wrong'
              ? // A chosen or typed answer says what it should have been,
                // the line the card shows; a flashcard's back is on screen.
                state.revealed !== undefined && (isChoice(card.type) || isTyped(card.type))
                ? t('session.wrongWas', { answer: state.revealed })
                : t('session.wrong')
              : '',
          tip === undefined ? '' : t(`tip.${tip}`),
        ]
          .filter((line) => line !== '')
          .join(' ')}
      </p>

      {state.celebrate && (
        // The prototype's small gold-edged card: it fades out on its own and
        // never blocks the next card.
        <div className={styles.celebrate} aria-live="polite">
          <div className={styles.celebrateCard}>
            <span className={styles.celebrateKicker}>{t('session.mastered')}</span>
            <span className={styles.celebrateWord}>{state.celebrate.headword}</span>
          </div>
        </div>
      )}

      {detailOpen && (
        <Sheet
          onClose={() => {
            setDetailOpen(false);
          }}
        >
          <WordDetail
            wordId={card.word.id}
            embedded
            onClose={() => {
              setDetailOpen(false);
            }}
          />
        </Sheet>
      )}

      {noteOpen && (
        <NoteSheet
          initial={card.word.progress?.memo ?? ''}
          headword={card.word.headword}
          onSave={(memo) => {
            void saveNote(memo);
            setNoteOpen(false);
          }}
          onClose={() => {
            setNoteOpen(false);
          }}
        />
      )}
    </main>
  );
}

/**
 * The tip a session card shows, if any (features/learn): the line under the
 * first flips in this device's first sessions (M2), at the first miss (M3),
 * at the first answer kept as practice (M8). This session is numbered once
 * it is running, which is what "the first two sessions" counts.
 */
function useCardTip(
  state: SessionState,
  flipped: boolean,
  holdFirstGrade: boolean,
): {
  tip: TipId | undefined;
  /**
   * Whether the line under the flips ("Be honest…") is one this session
   * gives, so the swipe coach can leave it its turn. True while the session
   * is still being numbered: waiting a moment is better than taking its card.
   */
  firstGradeDue: boolean;
} {
  const learn = useLearn();
  const tips = learn.on ? learn.tips : null;
  const running = state.status === 'running' && tips !== null;
  const [session, setSession] = useState<number | undefined>(undefined);
  const numbered = useRef(false);
  useEffect(() => {
    if (!running || numbered.current) return;
    numbered.current = true;
    void startTipSession().then((number) => {
      if (number !== undefined) setSession(number);
    });
  }, [running]);

  const { card, outcome, practised } = state;
  const flipCard = card !== undefined && !isChoice(card.type) && !isTyped(card.type);
  const pick =
    card === undefined || session === undefined
      ? undefined
      : pickTip(
          'card',
          {
            today: localDay(),
            session,
            wants: {
              firstGrade: flipCard && flipped && outcome === undefined && !holdFirstGrade,
              firstMiss: outcome === 'wrong',
              firstPracticeOnly: outcome === 'correct' && practised,
            },
          },
          tips,
        );
  const tip = useHeldTip(pick, `${card?.key ?? ''}:${outcome ?? 'asking'}`);
  // Unknown counts as due: the tips still being read or settled, or the
  // session still being numbered. Waiting a moment is better than the coach
  // taking a card the line was owed (it lost it on a quick flip, in a test).
  const settling = !learn.ready || (learn.on && learn.tips === null);
  const firstGradeDue =
    settling ||
    (tips !== null &&
      (session === undefined ||
        pickTip('card', { today: localDay(), session, wants: { firstGrade: true } }, tips) === 'firstGrade'));
  return { tip, firstGradeDue };
}

/** "Flashcard", "Multiple choice" — the prototype's own names for a type. */
/**
 * The question this card is asking, in a few words.
 *
 * One line per card type, because "what am I being asked to do" is the
 * first thing to know and each type asks something different.
 */
function askFor(type: CardType): string {
  const asks: Record<CardType, string> = {
    classic: t('session.askFlash'),
    reverse: t('session.askRecall'),
    mc: t('session.askChoice'),
    spell: t('session.askSpell'),
    cloze: t('session.askCloze'),
    audio: t('session.askListen'),
  };
  return asks[type];
}

function typeLabel(type: CardType): string {
  const labels: Record<CardType, string> = {
    classic: t('session.typeClassic'),
    reverse: t('session.typeReverse'),
    mc: t('session.typeMc'),
    spell: t('session.typeSpell'),
    cloze: t('session.typeCloze'),
    audio: t('session.typeAudio'),
  };
  return labels[type];
}
