import { useCallback, useEffect, useImperativeHandle, useLayoutEffect, useRef } from 'react';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { platform } from '@/lib/platform/index.js';
import { COACH_DEMO_MS, COACH_NUDGE_SHARE, COACH_TILT_DEG, COACH_TIMES, demoAt } from './coach.js';
import { canAnimate, currentOffset, fly, liftCopy, quiet, reducedMotion, type Flight } from './lift.js';
import {
  LEAVE_ROTATE_DEG,
  THROW_ROTATE_DEG,
  armedNow,
  commitPx,
  decideRelease,
  directionOf,
  followOf,
  inEdgeGuard,
  lockAxis,
  progressOf,
  rubberOf,
  throwMs,
  tiltOf,
  velocityOf,
  type Direction,
  type KnewSide,
  type Sample,
} from './physics.js';
import styles from './SwipeCard.module.css';

/**
 * - `grade`: a flashcard not graded yet; a swipe answers it.
 * - `next`: any card once answered; a swipe either way goes on.
 * - `rubber`: a card a swipe cannot answer (choice, cloze, spelling); it gives a little.
 * - `off`: nothing moves ("Swipe to answer" is off, or the card is busy).
 */
export type SwipeMode = 'grade' | 'next' | 'rubber' | 'off';

/** What the pill on a leaving card says. */
export type SwipeLabel = 'knew' | 'miss' | 'next';

/** What a session can ask of the card it holds. */
export interface SwipeHandle {
  /**
   * The card leaves towards `dir`: from where a swipe let it go when called
   * from `onCommit`, else from rest (a button, a key, a timer). The next
   * card is drawn under it; nothing waits for the flight. `label` keeps the
   * pill on a card that leaves from rest (a card skipped with the → key).
   */
  leave(dir: Direction, label?: SwipeLabel): void;
  /** Undo brought this card back: it slides in from the side it left by. */
  returnFrom(dir: Direction): void;
  /** The coach's demo (spec §9.3). Ends by itself, or at the learner's first touch. */
  demo(): void;
  /** Ends the demo at once (a key, a button), springing back. */
  stopDemo(): void;
}

interface SwipeCardProps {
  mode: SwipeMode;
  /** The card on screen. A new key puts the card back in its place, visible. */
  cardKey: string;
  /** A flashcard face: it gets the ring, the shadow and the blank card beneath. */
  flip: boolean;
  /** Which side of a flashcard is up: its front turns at a tap, so it keeps the pointer cursor. */
  face?: 'front' | 'back';
  /** The side "Knew it" is on. */
  knewSide: KnewSide;
  /** The face's corner radius, when it is not a session card's (`--r-card`). */
  radius?: string;
  /** A class for the frame around the card (the session's inner scroll box). */
  frameClassName?: string | undefined;
  /**
   * The screen (`<main>`), which carries `--sp`, `data-swipe-dir` and
   * `data-armed` while a card is dragged, so the buttons light in step.
   */
  host: React.RefObject<HTMLElement | null>;
  /** A swipe let go past the point, towards `dir`. Call `leave` in here to throw the card. */
  onCommit: (dir: Direction) => void;
  /**
   * A card that answered but stayed (a miss, a front that turns) is home
   * again: what changes on it (turning to the answer) happens now, so it
   * never shows under the card on its way back.
   */
  onLanded?: () => void;
  /** A drag took hold of the card, or let go of it: timers wait meanwhile. */
  onDrag?: (dragging: boolean) => void;
  ref?: React.Ref<SwipeHandle>;
  children: React.ReactNode;
}

interface Gesture {
  id: number;
  x0: number;
  y0: number;
  t0: number;
  /** Where the card already was when the press caught it (mid-demo, or flying home). */
  offset: number;
  locked: boolean;
  raw: number;
  width: number;
  armed: boolean;
  samples: Sample[];
}

/** The stand-in's class (CSS Modules types every class as possibly missing). */
const LIFTED = styles.lifted ?? '';

/** After a drag, a click on the card within this long belongs to the drag, not to what is under it. */
const CLICK_AFTER_DRAG_MS = 400;

/** Never a starting point: places to type and anything that opts out. */
const NO_SWIPE = 'input, textarea, select, [contenteditable], [data-no-swipe]';

/** A motion token in ms, read where the browser has it (tokens.css is the source). */
function tokenMs(name: string, fallback: number): number {
  const value = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  const ms = value.endsWith('ms') ? Number.parseFloat(value) : Number.NaN;
  return Number.isFinite(ms) ? ms : fallback;
}

/** A curve token, as the browser has it. */
function tokenEase(name: string, fallback: string): string {
  const value = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  return value === '' ? fallback : value;
}

/** Writes the drag's state where the pill, the ring, the plate and the buttons read it. */
function paintOn(
  elements: readonly (HTMLElement | null | undefined)[],
  lit: number,
  label: SwipeLabel,
  armed: boolean,
  side: Direction,
): void {
  for (const element of elements) {
    if (!element) continue;
    element.style.setProperty('--sp', lit.toFixed(3));
    element.dataset.swipeDir = label;
    element.dataset.side = String(side);
    if (armed) element.dataset.armed = '';
    else delete element.dataset.armed;
    element.dataset.swipeLive = '';
  }
}

/**
 * A practice card that can be swiped (uiux `specs/2026-10-25-practice-swipe.md`,
 * strict review `audits/2026-10-25-swipe-strict.md`).
 *
 * It follows the finger, tilts a little, and grows a pill ("Knew it",
 * "Didn't know", "Next"), a ring and a wash in that answer's colour, while
 * the matching button under it lights in step. Let go past the point (or
 * flick) and it answers; short of it, it springs back. The drag never
 * renders React: every frame is one write of a transform and `--sp`.
 *
 * What moves is a copy of the card on top of the page (`lift.ts`); the card
 * itself waits in its place, unseen, and is shown again in the same frame
 * the copy lands, so the two are never on screen together. A finger that
 * catches the copy on its way home carries on from where it is.
 *
 * Pointer Events only, so touch, pen and mouse take one path. A drag starts
 * only after a mostly sideways move (`touch-action: pan-y pinch-zoom` leaves
 * scrolling and zooming to the browser), never at a screen edge, never from
 * a field and never from a press held still; a click right after a drag is
 * swallowed, so the speaker or the tap-to-turn under the finger does not
 * fire too.
 */
export function SwipeCard({
  mode,
  cardKey,
  flip,
  face,
  knewSide,
  radius,
  frameClassName,
  host,
  onCommit,
  onLanded,
  onDrag,
  ref,
  children,
}: SwipeCardProps): React.JSX.Element {
  const deck = useRef<HTMLDivElement>(null);
  const card = useRef<HTMLDivElement>(null);
  const gesture = useRef<Gesture | undefined>(undefined);
  /** The card's stand-in while held: dragged, in the demo, or caught on its way home. */
  const copy = useRef<HTMLElement | undefined>(undefined);
  /** A stand-in flying home (a spring back, Undo's return), which a finger may catch. */
  const homing = useRef<{ stand: HTMLElement; flight: Flight } | undefined>(undefined);
  /**
   * What happens when the card is home (a front answered by a swipe turns).
   * Kept until it has run, whatever catches the card on its way: a tap or a
   * short drag that springs back still owes it (round 2 review R1).
   */
  const owedOnLanding = useRef<(() => void) | undefined>(undefined);
  /** Where the last swipe let go, for a `leave` called from `onCommit`. */
  const release = useRef<{ x: number; tilt: number; vx: number } | undefined>(undefined);
  /** The card left; it stays unseen until the next one takes its place. */
  const left = useRef(false);
  const demoRun = useRef<{ animation: Animation; frame: number } | undefined>(undefined);
  const frame = useRef<number | undefined>(undefined);
  const pressed = useRef(new Set<number>());
  const unbind = useRef<(() => void) | undefined>(undefined);

  // The latest props, for listeners that outlive a render.
  const latest = useRef({ mode, knewSide, onCommit, onLanded, onDrag });
  useLayoutEffect(() => {
    latest.current = { mode, knewSide, onCommit, onLanded, onDrag };
  });

  const unpaint = useCallback((): void => {
    for (const element of [host.current, deck.current]) {
      if (!element) continue;
      element.style.removeProperty('--sp');
      delete element.dataset.swipeDir;
      delete element.dataset.armed;
      delete element.dataset.swipeLive;
      delete element.dataset.side;
    }
  }, [host]);

  /** The card is seen again, unless something still stands in for it or it has left. */
  const show = useCallback((): void => {
    if (!card.current || left.current || copy.current || homing.current || demoRun.current) return;
    card.current.style.opacity = '';
  }, []);

  /** Puts the stand-in over the card, which steps out of sight but keeps its place. */
  const lift = useCallback((): HTMLElement | undefined => {
    if (copy.current) return copy.current;
    const source = card.current;
    if (!source) return undefined;
    copy.current = liftCopy(source, LIFTED, deck.current?.getBoundingClientRect());
    if (copy.current) source.style.opacity = '0';
    return copy.current;
  }, []);

  /** Takes back a stand-in flying home, where it is, for a new touch. Returns its offset. */
  const catchHoming = useCallback((): number => {
    const flying = homing.current;
    if (!flying) return 0;
    homing.current = undefined;
    flying.flight.catchIt();
    copy.current = flying.stand;
    return currentOffset(flying.stand);
  }, []);

  /**
   * The stand-in goes home, fully seen, and the card takes its place in the
   * frame it lands: never both at once (review B1). Then `landed`.
   */
  const settle = useCallback(
    (landed?: () => void): void => {
      unpaint();
      if (landed !== undefined) owedOnLanding.current = landed;
      const pay = (): void => {
        const owed = owedOnLanding.current;
        owedOnLanding.current = undefined;
        owed?.();
      };
      const stand = copy.current;
      copy.current = undefined;
      if (!stand) {
        show();
        pay();
        return;
      }
      delete stand.dataset.dragging;
      stand.style.setProperty('--sp', '0');
      const arrive = (): void => {
        if (homing.current?.stand === stand) homing.current = undefined;
        show();
        pay();
      };
      if (reducedMotion() || !canAnimate(stand)) {
        stand.remove();
        arrive();
        return;
      }
      const from = stand.style.transform === '' ? 'none' : stand.style.transform;
      const flight = fly(
        stand,
        [{ transform: from }, { transform: 'none' }],
        { duration: tokenMs('--dur-settle', 240), easing: tokenEase('--ease-settle', 'ease-out') },
        arrive,
      );
      if (stand.isConnected) homing.current = { stand, flight };
    },
    [show, unpaint],
  );

  const stopDemo = useCallback((): void => {
    const run = demoRun.current;
    if (!run) return;
    demoRun.current = undefined;
    cancelAnimationFrame(run.frame);
    const stand = copy.current;
    if (stand) {
      const here = getComputedStyle(stand).transform;
      stand.style.transform = here === '' ? 'none' : here;
    }
    run.animation.cancel();
  }, []);

  const endGesture = useCallback((): void => {
    unbind.current?.();
    unbind.current = undefined;
    if (frame.current !== undefined) cancelAnimationFrame(frame.current);
    frame.current = undefined;
    const was = gesture.current;
    gesture.current = undefined;
    if (was?.locked) latest.current.onDrag?.(false);
  }, []);

  /** Draws the drag as it is now: one write per frame. */
  const draw = useCallback((): void => {
    frame.current = undefined;
    const now = gesture.current;
    const stand = copy.current;
    if (!now?.locked) return;
    const { mode: current, knewSide: side } = latest.current;
    const rubber = current === 'rubber';
    const x = rubber ? rubberOf(now.raw) : followOf(now.raw, now.width);
    const tilt = rubber || reducedMotion() ? 0 : tiltOf(x, now.width);
    if (stand) stand.style.transform = `translate3d(${String(x)}px, 0, 0) rotate(${String(tilt)}deg)`;
    if (rubber) return;
    const armed = armedNow(now.raw, now.width, now.armed);
    if (armed !== now.armed) {
      now.armed = armed;
      platform.haptics.tick();
    }
    const dir = directionOf(now.raw);
    const label: SwipeLabel = current === 'next' ? 'next' : dir === side ? 'knew' : 'miss';
    paintOn([host.current, deck.current, stand], progressOf(now.raw, now.width), label, armed, dir);
  }, [host]);

  const swallowNextClick = useCallback((): void => {
    const until = performance.now() + CLICK_AFTER_DRAG_MS;
    const onClick = (event: MouseEvent): void => {
      window.removeEventListener('click', onClick, true);
      if (performance.now() > until) return;
      if (event.target instanceof Node && card.current?.contains(event.target)) {
        event.preventDefault();
        event.stopPropagation();
      }
    };
    window.addEventListener('click', onClick, true);
    window.setTimeout(() => {
      window.removeEventListener('click', onClick, true);
    }, CLICK_AFTER_DRAG_MS);
  }, []);

  const cancel = useCallback((): void => {
    const was = gesture.current;
    endGesture();
    if (was?.locked) swallowNextClick();
    if (copy.current) settle();
  }, [endGesture, settle, swallowNextClick]);

  const finish = useCallback((): void => {
    const now = gesture.current;
    if (!now) return;
    if (!now.locked) {
      endGesture();
      // A tap that caught the demo or a card on its way home: it goes home.
      if (copy.current) settle();
      return;
    }
    const vx = velocityOf(now.samples, performance.now());
    const { mode: current } = latest.current;
    // A card caught on its way home answers only if the finger itself
    // pushed it outwards: moving it back towards the middle is letting go.
    const pushedOut = now.offset === 0 || Math.sign(now.raw - now.offset) === Math.sign(now.raw);
    const decision = current === 'rubber' || !pushedOut ? 'cancel' : decideRelease(now.raw, vx, now.width);
    const x = followOf(now.raw, now.width);
    endGesture();
    swallowNextClick();
    if (decision === 'cancel') {
      settle();
      return;
    }
    const dir = directionOf(now.raw);
    if (current === 'next') platform.haptics.select();
    release.current = { x, tilt: reducedMotion() ? 0 : tiltOf(x, now.width), vx };
    latest.current.onCommit(dir);
    release.current = undefined;
    // Not thrown (a miss that waits, a front that turns): home, then it changes.
    if (!left.current) settle(() => latest.current.onLanded?.());
  }, [endGesture, settle, swallowNextClick]);

  const onPointerDown = (event: React.PointerEvent<HTMLDivElement>): void => {
    pressed.current.add(event.pointerId);
    if (gesture.current) {
      // A second finger: a pinch or a slip, never a swipe.
      cancel();
      return;
    }
    if (pressed.current.size > 1) return;
    if (latest.current.mode === 'off' || !event.isPrimary || event.button !== 0) return;
    if (inEdgeGuard(event.clientX, window.innerWidth)) return;
    if (event.target instanceof Element && event.target.closest(NO_SWIPE)) return;

    // Caught mid-demo or on its way home: the drag carries on from where the card is.
    let offset = 0;
    if (demoRun.current) {
      offset = copy.current ? currentOffset(copy.current) : 0;
      stopDemo();
    } else if (homing.current) {
      offset = catchHoming();
    }
    const now: Gesture = {
      id: event.pointerId,
      x0: event.clientX,
      y0: event.clientY,
      t0: performance.now(),
      offset,
      locked: false,
      raw: offset,
      width: card.current?.clientWidth ?? 0,
      armed: false,
      samples: [],
    };
    gesture.current = now;

    const onMove = (move: PointerEvent): void => {
      if (move.pointerId !== now.id || gesture.current !== now) return;
      const dx = move.clientX - now.x0;
      const dy = move.clientY - now.y0;
      if (!now.locked) {
        const axis = lockAxis(dx, dy, performance.now() - now.t0);
        if (axis === undefined) return;
        if (axis !== 'x') {
          // A scroll or a held press: the browser's, for the rest of this touch.
          endGesture();
          if (copy.current) settle();
          return;
        }
        now.locked = true;
        // Nothing to draw (no layout) still answers: the copy is only the picture.
        const stand = lift();
        if (stand) stand.dataset.dragging = '';
        try {
          card.current?.setPointerCapture(now.id);
        } catch {
          // A pointer the browser no longer tracks: the window listeners still follow it.
        }
        window.getSelection()?.removeAllRanges();
        latest.current.onDrag?.(true);
      }
      move.preventDefault();
      now.raw = now.offset + dx;
      now.samples.push({ x: move.clientX, at: performance.now() });
      if (now.samples.length > 12) now.samples.shift();
      frame.current ??= requestAnimationFrame(draw);
    };
    const onUp = (up: PointerEvent): void => {
      pressed.current.delete(up.pointerId);
      if (up.pointerId === now.id && gesture.current === now) finish();
    };
    const onCancel = (lost: PointerEvent): void => {
      pressed.current.delete(lost.pointerId);
      if (lost.pointerId === now.id && gesture.current === now) cancel();
    };
    window.addEventListener('pointermove', onMove, { passive: false });
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onCancel);
    unbind.current = () => {
      window.removeEventListener('pointermove', onMove);
      window.removeEventListener('pointerup', onUp);
      window.removeEventListener('pointercancel', onCancel);
    };
  };

  useImperativeHandle(
    ref,
    (): SwipeHandle => ({
      leave(dir, label) {
        owedOnLanding.current = undefined;
        stopDemo();
        if (homing.current) catchHoming();
        const thrown = release.current;
        const source = card.current;
        unpaint();
        if (!source) return;
        if (reducedMotion() || !canAnimate(source)) {
          // Less motion: the next card simply takes its place.
          copy.current?.remove();
          copy.current = undefined;
          return;
        }
        const stand = copy.current ?? liftCopy(source, LIFTED, deck.current?.getBoundingClientRect());
        copy.current = undefined;
        if (!stand) return;
        delete stand.dataset.dragging;
        left.current = true;
        source.style.opacity = '0';
        const box = source.getBoundingClientRect();
        // Clear of the screen's edge, tilt included.
        const reach = dir > 0 ? window.innerWidth - box.left : box.right;
        const to = dir * (reach + box.height * 0.25 + 40);
        if (thrown) {
          fly(
            stand,
            [
              {
                transform: `translate3d(${String(thrown.x)}px, 0, 0) rotate(${String(thrown.tilt)}deg)`,
                opacity: 1,
              },
              { opacity: 1, offset: 0.6 },
              {
                transform: `translate3d(${String(to)}px, 0, 0) rotate(${String(dir * THROW_ROTATE_DEG)}deg)`,
                opacity: 0,
              },
            ],
            {
              duration: throwMs(Math.abs(to - thrown.x), thrown.vx),
              easing: tokenEase('--ease-throw', 'ease-out'),
            },
          );
          return;
        }
        // Graded some other way: it still leaves towards its side, which
        // teaches the direction on every answer and costs no time. A card
        // skipped with a key says so on its way, as a swiped one does.
        if (label === undefined) stand.style.setProperty('--sp', '0');
        else paintOn([stand], 1, label, false, dir);
        fly(
          stand,
          [
            { transform: 'none', opacity: 1 },
            { opacity: 1, offset: 0.5 },
            {
              transform: `translate3d(${String(to)}px, 0, 0) rotate(${String(dir * LEAVE_ROTATE_DEG)}deg)`,
              opacity: 0,
            },
          ],
          { duration: tokenMs('--dur-leave', 200), easing: tokenEase('--ease-leave', 'ease-in') },
        );
      },
      returnFrom(dir) {
        const source = card.current;
        if (!source || reducedMotion() || !canAnimate(source)) return;
        const stand = lift();
        if (!stand) return;
        copy.current = undefined;
        const width = source.getBoundingClientRect().width;
        const flight = fly(
          stand,
          [
            {
              transform: `translate3d(${String(dir * 0.6 * width)}px, 0, 0) rotate(${String(dir * 6)}deg)`,
              opacity: 0,
            },
            { transform: 'none', opacity: 1 },
          ],
          { duration: tokenMs('--dur-settle', 240), easing: tokenEase('--ease-settle', 'ease-out') },
          () => {
            if (homing.current?.stand === stand) homing.current = undefined;
            show();
          },
        );
        if (stand.isConnected) homing.current = { stand, flight };
      },
      demo() {
        if (demoRun.current || gesture.current || copy.current || homing.current) return;
        const source = card.current;
        if (!source || reducedMotion() || !canAnimate(source)) return;
        const stand = lift();
        if (!stand) return;
        const side = latest.current.knewSide;
        // As far as a real drag that lights the pill this much, never far enough to answer.
        const nudge = COACH_NUDGE_SHARE * commitPx(source.clientWidth);
        const at = (share: number, tilt: number): string =>
          `translate3d(${String(side * share * nudge)}px, 0, 0) rotate(${String(side * tilt)}deg)`;
        const easing = tokenEase('--ease-fly', 'ease-in-out');
        const { out, hold, back, out2, hold2 } = COACH_TIMES;
        const animation = stand.animate(
          [
            { transform: at(0, 0), offset: 0, easing },
            { transform: at(1, COACH_TILT_DEG), offset: out / COACH_DEMO_MS },
            { transform: at(1, COACH_TILT_DEG), offset: hold / COACH_DEMO_MS, easing },
            { transform: at(0, 0), offset: back / COACH_DEMO_MS, easing },
            { transform: at(-1, -COACH_TILT_DEG), offset: out2 / COACH_DEMO_MS },
            { transform: at(-1, -COACH_TILT_DEG), offset: hold2 / COACH_DEMO_MS, easing },
            { transform: at(0, 0), offset: 1 },
          ],
          { duration: COACH_DEMO_MS, fill: 'forwards' },
        );
        quiet(animation);
        const step = (): void => {
          const run = demoRun.current;
          if (run?.animation !== animation) return;
          const { side: lean, lit } = demoAt(Number(animation.currentTime ?? 0));
          const dir = (lean * side) as Direction;
          paintOn([host.current, deck.current, stand], lit, dir === side ? 'knew' : 'miss', false, dir);
          run.frame = requestAnimationFrame(step);
        };
        demoRun.current = { animation, frame: requestAnimationFrame(step) };
        animation.addEventListener('finish', () => {
          if (demoRun.current?.animation !== animation) return;
          cancelAnimationFrame(demoRun.current.frame);
          demoRun.current = undefined;
          unpaint();
          copy.current?.remove();
          copy.current = undefined;
          show();
        });
      },
      stopDemo() {
        if (!demoRun.current) return;
        stopDemo();
        settle();
      },
    }),
    [catchHoming, host, lift, settle, show, stopDemo, unpaint],
  );

  // A new card takes the place: seen, at rest, whatever the last one did.
  useLayoutEffect(() => {
    left.current = false;
    owedOnLanding.current = undefined;
    if (card.current && !copy.current && !homing.current) card.current.style.opacity = '';
  }, [cardKey]);

  // A mode that no longer swipes (a sheet opened, the setting went off) lets go of the card.
  useEffect(() => {
    if (mode === 'off' && gesture.current) cancel();
  }, [mode, cancel]);

  // Leaving the app mid-drag springs the card back; unmounting tidies up.
  useEffect(() => {
    const onHidden = (): void => {
      if (document.visibilityState !== 'hidden') return;
      if (gesture.current) cancel();
      if (demoRun.current) {
        stopDemo();
        settle();
      }
    };
    document.addEventListener('visibilitychange', onHidden);
    return () => {
      document.removeEventListener('visibilitychange', onHidden);
      unbind.current?.();
      if (demoRun.current) {
        cancelAnimationFrame(demoRun.current.frame);
        demoRun.current.animation.cancel();
        demoRun.current = undefined;
      }
      // A card in flight finishes on its own; a stand-in still held goes now.
      copy.current?.remove();
      copy.current = undefined;
      unpaint();
    };
  }, [cancel, settle, stopDemo, unpaint]);

  const cornerStyle =
    radius === undefined ? undefined : ({ '--swipe-radius': radius } as React.CSSProperties);
  return (
    <div ref={deck} className={cx(styles.deck, frameClassName)} data-flip={flip ? '' : undefined}>
      <div className={styles.pile} style={cornerStyle}>
        {flip && mode !== 'off' && <div className={styles.plate} aria-hidden="true" />}
        <div
          ref={card}
          className={styles.card}
          data-flip={flip ? '' : undefined}
          data-face={face}
          data-mode={mode}
          style={cornerStyle}
          onPointerDown={onPointerDown}
        >
          {children}
          <span className={styles.pills} aria-hidden="true">
            <span className={cx(styles.pill, styles.pillKnew)}>
              <Icon name="check" size={16} weight={2.4} />
              {t('session.knewIt')}
            </span>
            <span className={cx(styles.pill, styles.pillMiss)}>
              <Icon name="close" size={16} weight={2.4} />
              {t('session.didntKnow')}
            </span>
            <span className={cx(styles.pill, styles.pillNext)}>
              <Icon name="arrowRight" size={16} weight={2.4} />
              {t('session.next')}
            </span>
          </span>
        </div>
      </div>
    </div>
  );
}
